  'Task': 'Tâche',
  'The task is on the date found. {summary} is the line it was in without the date, {line} the whole line, {time} its time (tasks have no time of their own, so it goes into the text), {title} the note\'s title': 'La tâche est à la date trouvée. {summary} est la ligne où elle se trouvait sans la date, {line} la ligne entière, {time} son heure (les tâches n’ont pas d’heure propre, elle va donc dans le texte), {title} le titre de la note',
  '{title} is the note\'s title, {date} today\'s date': '{title} est le titre de la note, {date} la date du jour',
  'Improve the title with the language model': 'Améliorer le titre avec le modèle de langue',
  'Rewrites {summary} when the model from Settings is installed; otherwise it stays as it is': 'Réécrit {summary} quand le modèle des réglages est installé ; sinon il reste tel quel',
  'Due: {when}': 'Échéance : {when}',
  'Reads the pen writing of each page in the background and puts the text in a box under it. A page is read again only when its writing changes. Needs the handwriting model from Settings; a page takes a while on a tablet.': 'Lit l’écriture à la plume de chaque page en arrière-plan et met le texte dans une zone sous elle. Une page n’est relue que quand son écriture change. Nécessite le modèle d’écriture manuscrite des réglages ; une page prend un moment sur une tablette.',
  'A language model on this device reads the note and compares it with the notes in each folder; the note goes to the folder it resembles most, if that is clear enough. Needs the sentence model from Settings. The notes of a folder are read once, and again only when they change.': 'Un modèle de langue sur cet appareil lit la note et la compare aux notes de chaque dossier ; la note va dans le dossier auquel elle ressemble le plus, si c’est assez clair. Nécessite le modèle de phrases des réglages. Les notes d’un dossier sont lues une fois, et à nouveau seulement quand elles changent.',
