  'Leave': 'Quitter',
  'Start a live session and send the link to whoever should join. Everything that is drawn or written shows up for everyone at once. What is sent is sealed with a key that only the link contains: nobody in between (not even the server that introduces your devices to each other) can read it. The session lasts as long as you keep this note open and the app running.': 'Démarrez une session en direct et envoyez le lien à ceux qui doivent se joindre. Tout ce qui est dessiné ou écrit apparaît pour tout le monde en même temps. Ce qui est envoyé est scellé par une clé que seul le lien contient : personne entre les deux (pas même le serveur qui présente vos appareils l’un à l’autre) ne peut le lire. La session dure tant que vous gardez cette note ouverte et l’application lancée.',
