  'Platform look': 'Style de la plateforme',
  'Automatic dresses the app like an iPhone app on an iPhone or iPad, and like a Material app elsewhere. Pick one to see it on any device.': 'Automatique adopte le style d’une application iPhone sur iPhone ou iPad, et celui d’une application Material ailleurs. Choisissez-en un pour le voir sur n’importe quel appareil.',
  'Material': 'Material',
  'Colors the buttons, selections and markers in every part of the app.': 'Colore les boutons, sélections et repères dans toutes les parties de l’application.',
  'Button': 'Bouton',
  'Chip': 'Puce',
  'Language model': 'Modèle de langue',
  'Titles for tasks from PDFs': 'Titres des tâches tirées des PDF',
  'Record a meeting on the dashboard, or dictate into a note, and what is said is written down. It happens on this device (Whisper, MIT and Apache-2.0 licences); the sound is never sent away and not kept.': 'Enregistrez une réunion depuis le tableau de bord ou dictez dans une note : ce qui est dit est écrit. Cela se passe sur cet appareil (Whisper, licences MIT et Apache-2.0) ; le son n’est jamais envoyé ailleurs ni conservé.',
  'Writes short titles for the tasks that automations make from dates in a PDF (Qwen3-0.6B, Apache-2.0 licence). It runs on this device and nothing is sent away; it is loaded only while it works. It needs a fair amount of memory while it does.': 'Rédige de courts titres pour les tâches créées par les automatisations à partir des dates d’un PDF (Qwen3-0.6B, licence Apache-2.0). Il fonctionne sur cet appareil et rien n’est envoyé ailleurs ; il n’est chargé que pendant son travail, et il demande alors une bonne quantité de mémoire.',
  'Colors, borders and emoji for the calendar itself are set in the Calendar tab, with the palette button at the top.': 'Les couleurs, bordures et emoji de l’agenda lui-même se règlent dans l’onglet Agenda, avec le bouton palette en haut.',
  'Original blue': 'Bleu d’origine',
  '{description} It needs a model of about {size} MB.': '{description} Il faut un modèle d’environ {size} Mo.',
  'Model installed': 'Modèle installé',
  'Model not installed': 'Modèle non installé',
  'Download failed: {error}': 'Échec du téléchargement : {error}',
  'The server answers.': 'Le serveur répond.',
  'Live collaboration': 'Collaboration en direct',
  'Work on a note together with others at the same time. Everything is sealed with a key that only the invite link holds; the signalling server only introduces your devices to each other and sees nothing of the note (but it does see the addresses of the devices that connect, and when). You can use the one that comes with the app or run your own: the source has versions for Cloudflare Workers, Node and Dart in tool/signaling. Everyone in a session uses the server of whoever made the invite.': 'Travaillez sur une note avec d’autres en même temps. Tout est scellé par une clé que seul le lien d’invitation contient ; le serveur de signalisation ne fait que présenter vos appareils l’un à l’autre et ne voit rien de la note (mais il voit les adresses des appareils qui se connectent, et quand). Vous pouvez utiliser celui fourni avec l’application ou faire tourner le vôtre : les sources contiennent des versions pour Cloudflare Workers, Node et Dart dans tool/signaling. Tous les participants d’une session utilisent le serveur de celui qui a fait l’invitation.',
  'Built-in server': 'Serveur intégré',
  'My own server': 'Mon propre serveur',
  'Test and use': 'Tester et utiliser',
  'Using the built-in server.': 'Utilisation du serveur intégré.',
  'Your name in sessions': 'Votre nom dans les sessions',
  'Note files': 'Fichiers de note',
  'A note can be saved as one file (.uninote, a ZIP with the text, the strokes, pictures and the PDF) to keep, send, or open on another device: use "Save this note as a file" in the note, or the menu of a note. To have a file made by itself whenever a note was changed (into a folder that a sync program watches, say), add the automation "Save the note as a file" in the Automations tab.': 'Une note peut être enregistrée dans un seul fichier (.uninote, une archive ZIP avec le texte, les tracés, les images et le PDF) pour la garder, l’envoyer ou l’ouvrir sur un autre appareil : utilisez « Enregistrer cette note comme fichier » dans la note, ou le menu d’une note. Pour qu’un fichier se crée tout seul à chaque modification d’une note (dans un dossier surveillé par un programme de synchronisation, par exemple), ajoutez l’automatisation « Enregistrer la note comme fichier » dans l’onglet Automatisations.',
  'Open a note file...': 'Ouvrir un fichier de note...',
  'Sorting notes': 'Tri des notes',
  'Sentence model': 'Modèle de phrases',
  'Reads the meaning of a note with a small language model (a sentence transformer, Apache-2.0 licence). It files notes by the automation "Move the note to the folder it fits best", finds the passages that answer a question across all notes, and makes the graph follow the meaning. It runs on this device; nothing is sent away.': 'Lit le sens d’une note avec un petit modèle de langue (un transformeur de phrases, licence Apache-2.0). Il range les notes grâce à l’automatisation « Déplacer la note dans le dossier qui lui correspond le mieux », trouve les passages qui répondent à une question dans toutes les notes, et fait suivre le sens au graphe. Il fonctionne sur cet appareil ; rien n’est envoyé ailleurs.',
  'The automation "Move the note to the folder it fits best" reads the words of a note with a small language model (a sentence transformer, Apache-2.0 licence) and files it with the notes it resembles. It runs on this device; nothing is sent away.': 'L’automatisation « Déplacer la note dans le dossier qui lui correspond le mieux » lit les mots d’une note avec un petit modèle de langue (un transformeur de phrases, licence Apache-2.0) et la range avec les notes auxquelles elle ressemble. Il fonctionne sur cet appareil ; rien n’est envoyé ailleurs.',
  'Handwriting': 'Écriture manuscrite',
  'Select drawings with the lasso and choose "Convert handwriting to text". Reading happens on this device; nothing is sent away.': 'Sélectionnez des dessins avec le lasso et choisissez « Convertir l’écriture en texte ». La lecture se fait sur cet appareil ; rien n’est envoyé ailleurs.',
  'Which model reads the handwriting': 'Quel modèle lit l’écriture',
  'GLM-OCR (MIT licence) reads each line of your writing as a picture, with the knowledge of a language model about which words are likely: far better than the others on German and English notes. About 800 MB to download and two to three gigabytes of memory while it reads; it may correct a word to English or write maths as LaTeX.': 'GLM-OCR (licence MIT) lit chaque ligne de votre écriture comme une image, avec la connaissance d’un modèle de langue sur les mots probables : nettement meilleur que les autres sur les notes en allemand et en anglais. Environ 800 Mo à télécharger et deux à trois gigaoctets de mémoire pendant la lecture ; il peut corriger un mot en anglais ou écrire les maths en LaTeX.',
  'How carefully it looks': 'Précision de la lecture',
  'Quick': 'Rapide',
  'Quick takes about two thirds of the time and reads a little less exactly. Light takes less than half of it and reads clearly less exactly: for a slow device.': 'Rapide prend environ les deux tiers du temps et lit un peu moins exactement. Léger en prend moins de la moitié et lit nettement moins exactement : pour un appareil lent.',
  'PaddleOCR-VL (Apache 2.0 licence) is a much bigger model: about 900 MB to download, a gigabyte or two of memory while it reads, and slow on a tablet. It reads each line of your writing as a picture, with the knowledge of a language model about which words are likely.': 'PaddleOCR-VL (licence Apache 2.0) est un modèle bien plus gros : environ 900 Mo à télécharger, un ou deux gigaoctets de mémoire pendant la lecture, et lent sur une tablette. Il lit chaque ligne de votre écriture comme une image, avec la connaissance d’un modèle de langue sur les mots probables.',
  'Formulas': 'Formules',
  'Select a handwritten formula with the lasso and choose "Convert a handwritten formula to LaTeX". Reading happens on this device; nothing is sent away.': 'Sélectionnez une formule manuscrite avec le lasso et choisissez « Convertir une formule manuscrite en LaTeX ». La lecture se fait sur cet appareil ; rien n’est envoyé ailleurs.',
  'Which model reads the formulas': 'Quel modèle lit les formules',
  'TexTeller (Apache 2.0 licence) reads handwriting far better, but is bigger and slower. It suits a computer or a fast tablet.': 'TexTeller (licence Apache 2.0) lit l’écriture manuscrite bien mieux, mais il est plus gros et plus lent. Il convient à un ordinateur ou à une tablette rapide.',
  'Pix2Text (MIT licence) is lighter and quicker, but made for printed formulas and poor at handwriting. Use it if the device is slow or short of memory.': 'Pix2Text (licence MIT) est plus léger et plus rapide, mais conçu pour les formules imprimées et médiocre en écriture manuscrite. Utilisez-le si l’appareil est lent ou manque de mémoire.',
  'AI assistant': 'Assistant IA',
  'Highlight text and choose "Summarize" (more than two words), "Tell me more" or "Ask a question"; the sparkle button in a note opens an assistant that answers questions about the whole document. Who answers is up to you; the text you highlight goes to that provider only.': 'Surlignez du texte et choisissez « Résumer » (plus de deux mots), « En savoir plus » ou « Poser une question » ; le bouton étincelle d’une note ouvre un assistant qui répond aux questions sur tout le document. Le fournisseur qui répond est à votre choix ; le texte surligné n’est envoyé qu’à ce fournisseur.',
  'Prompt for "Summarize"': 'Consigne pour « Résumer »',
  'Standing instructions': 'Consignes permanentes',
  'Request': 'Demande',
  '{text} is the highlighted text, {length} how long the summary should be': '{text} est le texte surligné, {length} la longueur souhaitée du résumé',
  'Length': 'Longueur',
  'Back to the standard prompt': 'Revenir à la consigne standard',
  'Found on this computer. Needs {needs}.': 'Trouvé sur cet ordinateur. Nécessite {needs}.',
  'Needs {needs}.': 'Nécessite {needs}.',
  'The download failed: {why}': 'Le téléchargement a échoué : {why}',
  'No graphics card runtime downloaded yet. Pick one above; it is used from the next start of the app.': 'Aucun environnement de carte graphique téléchargé pour l’instant. Choisissez-en un ci-dessus ; il sera utilisé au prochain démarrage de l’application.',
  'NVIDIA graphics card (CUDA 13)': 'Carte graphique NVIDIA (CUDA 13)',
  'NVIDIA graphics card (CUDA 12)': 'Carte graphique NVIDIA (CUDA 12)',
  'AMD graphics card (ROCm)': 'Carte graphique AMD (ROCm)',
  'Intel graphics card / NPU (OpenVINO)': 'Carte graphique Intel / NPU (OpenVINO)',
  'the NVIDIA driver 580 or newer, and CUDA 13 with cuDNN': 'le pilote NVIDIA 580 ou plus récent, et CUDA 13 avec cuDNN',
  'the NVIDIA driver, and CUDA 12 with cuDNN': 'le pilote NVIDIA, et CUDA 12 avec cuDNN',
  'ROCm 7.1': 'ROCm 7.1',
  'the Intel compute runtime': 'le runtime de calcul Intel',
  'This computer has a graphics card ({names}), but the app is running on the runtime for the processor. Download the runtime for it below, then start the app again.': 'Cet ordinateur a une carte graphique ({names}), mais l’application tourne sur l’environnement du processeur. Téléchargez ci-dessous l’environnement qui lui correspond, puis relancez l’application.',
  'Show extra small models': 'Afficher les très petits modèles',
