  'e.g. gpt-4o-mini or llama3.2': 'p. ex. gpt-4o-mini ou llama3.2',
  'API key': 'Clé API',
  'A key is saved in this device\'s keystore; leave empty to keep it. Servers on your own machine often need none.': 'Une clé est enregistrée dans le trousseau de cet appareil ; laissez vide pour la conserver. Les serveurs sur votre propre machine n’en ont souvent pas besoin.',
  'Kept in this device\'s keystore. Servers on your own machine often need none.': 'Conservée dans le trousseau de cet appareil. Les serveurs sur votre propre machine n’en ont souvent pas besoin.',
  'Trying...': 'Essai en cours...',
  'Save and try': 'Enregistrer et essayer',
  'Delete the key': 'Supprimer la clé',
  'AI features': 'Fonctions IA',
  'On': 'Activées',
  'Off: nothing in the app uses AI': 'Désactivées : rien dans l’application n’utilise l’IA',
  'Turn this off and every AI feature goes away at once: the assistant, summaries and questions about highlighted text, smart task titles, reading handwriting and formulas. Nothing is run, and nothing is sent to an AI service. Your downloads and settings below stay as they are.': 'Désactivez-les et toutes les fonctions d’IA disparaissent d’un coup : l’assistant, les résumés et questions sur le texte surligné, les titres de tâches intelligents, la lecture de l’écriture manuscrite et des formules. Rien ne tourne et rien n’est envoyé à un service d’IA. Vos téléchargements et réglages ci-dessous restent tels quels.',
  'Language': 'Langue',
  'The language of the menus and messages. By default the language of the device is used.': 'La langue des menus et des messages. Par défaut, c’est la langue de l’appareil qui est utilisée.',
