  'Could not look for shares given to you. {why}': 'Impossible de rechercher les partages qui vous sont adressés. {why}',
  'The Nextcloud refused {method} at {url} (405). Check that the address of the Nextcloud in the settings under Sync and sharing is the one you open in the browser.': 'Le Nextcloud a refusé {method} à {url} (405). Vérifiez que l’adresse du Nextcloud dans les réglages, sous Synchronisation et partage, est celle que vous ouvrez dans le navigateur.',
  'This link does not use a secure address.': 'Ce lien n’utilise pas une adresse sécurisée.',
  'This shared copy is gone: it expired or was taken down.': 'Cette copie partagée n’existe plus : elle a expiré ou a été retirée.',
  'The shared copy could not be downloaded ({code}).': 'La copie partagée n’a pas pu être téléchargée ({code}).',
  'This shared copy is too big.': 'Cette copie partagée est trop grosse.',
  'This calendar is too big.': 'Cet agenda est trop gros.',
  'This copy cannot be opened: the link is incomplete, or the file was changed.': 'Cette copie ne peut pas être ouverte : le lien est incomplet, ou le fichier a été modifié.',
  'Puts a sealed copy of this note on {service} and makes a link to it. Whoever opens the link gets their own copy, even while you are offline. Only the link can open the copy; {service} sees a file it cannot read. The link works for {days} days.': 'Dépose une copie scellée de cette note sur {service} et crée un lien vers elle. Celui qui ouvre le lien obtient sa propre copie, même quand vous êtes hors ligne. Seul le lien peut ouvrir la copie ; {service} voit un fichier qu’il ne peut pas lire. Le lien fonctionne pendant {days} jours.',
