  'The file was stored but cannot be downloaded through a signed link ({code}). Is the region right?': 'Le fichier a été enregistré mais ne peut pas être téléchargé par un lien signé ({code}). La région est-elle bonne ?',
  'Sharing copies of notes': 'Partage de copies de notes',
  'A copy of a note can be put on a storage service you have an account with, and opened by anyone with the link, also while you are offline. The copy is sealed with a key that is only in the link: the service stores a file it cannot read. Several services can be set up; the one chosen when you share is used.': 'Une copie de note peut être déposée sur un service de stockage dont vous avez un compte, et ouverte par quiconque a le lien, même hors ligne. La copie est scellée par une clé qui n’est que dans le lien : le service stocke un fichier qu’il ne peut pas lire. Plusieurs services peuvent être configurés ; c’est celui choisi au moment du partage qui est utilisé.',
  'The address must start with https://': 'L’adresse doit commencer par https://',
  'It works. Copies can be shared through this bucket.': 'Ça fonctionne. Des copies peuvent être partagées par ce bucket.',
  'Any S3-compatible service: Cloudflare R2, Backblaze B2, Wasabi, MinIO, Amazon S3. Make an access key that may read and write in one bucket. Links work for 7 days; the copies are deleted from the bucket after that, the next time you share.': 'Tout service compatible S3 : Cloudflare R2, Backblaze B2, Wasabi, MinIO, Amazon S3. Créez une clé d’accès autorisée à lire et écrire dans un seul bucket. Les liens fonctionnent 7 jours ; les copies sont ensuite supprimées du bucket, au prochain partage.',
  'Bucket {bucket} at {host}': 'Bucket {bucket} sur {host}',
