  'The browser could not be opened.': 'Le navigateur n’a pas pu être ouvert.',
  'Copies are put in a folder of the app on your {service}, and the link works for {days} days; the copies are deleted from it after that, the next time you share.': 'Les copies sont déposées dans un dossier de l’application sur votre {service}, et le lien fonctionne {days} jours ; les copies y sont ensuite supprimées, au prochain partage.',
  'Sign in to {service}': 'Se connecter à {service}',
  'Sign out': 'Se déconnecter',
  'Change': 'Modifier',
  'While you work on this note in a live session, whoever opens this link is offered to join it.': 'Pendant que vous travaillez sur cette note en session en direct, quiconque ouvre ce lien se voit proposer de la rejoindre.',
  'Someone is working on this note right now': 'Quelqu’un travaille sur cette note en ce moment',
  '{who} is in a live session on this note. Join it and work on the note together, or open a copy of your own?': '{who} est dans une session en direct sur cette note. La rejoindre pour travailler ensemble sur la note, ou ouvrir une copie à vous ?',
