  'Application (client) ID': 'Identifiant d’application (client)',
  'Dropbox needs an app of your own: create one at dropbox.com/developers/apps ("Scoped access", "App folder"), allow files.content.write and sharing.write, add the redirect URI notation://oauth/dropbox, and enter its app key here.': 'Dropbox a besoin d’une application à vous : créez-en une sur dropbox.com/developers/apps (« Scoped access », « App folder »), autorisez files.content.write et sharing.write, ajoutez l’URI de redirection notation://oauth/dropbox, et saisissez ici sa clé d’application.',
  'OneDrive needs an app of your own: register one in the Azure portal (App registrations, accounts of any kind), add the redirect URI notation://oauth/onedrive for "Mobile and desktop", allow Files.ReadWrite.AppFolder and offline_access, and enter its application ID here.': 'OneDrive a besoin d’une application à vous : enregistrez-en une dans le portail Azure (App registrations, comptes de tout type), ajoutez l’URI de redirection notation://oauth/onedrive pour « Mobile and desktop », autorisez Files.ReadWrite.AppFolder et offline_access, et saisissez ici son identifiant d’application.',
