  'A paint roller for the drawing bar: a wide band with streaks.': 'Un rouleau de peinture pour la barre de dessin : une large bande aux stries.',
  'Import a PDF to write on, and export a note as a PDF.': 'Importer un PDF où écrire, et exporter une note en PDF.',
  'Languages': 'Langues',
  'Lasso': 'Lasso',
  'Law, business, economics and social sciences': 'Droit, économie, gestion et sciences sociales',
  'Lines drawn nearly straight are straightened, and drawings very close to a rectangle, ellipse, triangle or diamond become that shape.': 'Les lignes tracées presque droites sont redressées, et les dessins très proches d’un rectangle, d’une ellipse, d’un triangle ou d’un losange deviennent cette forme.',
  'Lines, arrows, rectangles and ellipses drawn with the pen.': 'Lignes, flèches, rectangles et ellipses tracés au stylo.',
  'Live sessions and shared copies of notes with other people.': 'Sessions en direct et copies partagées de notes avec d’autres personnes.',
  'Look things up': 'Chercher des informations',
  'Made for you now and kept. If two people with the same name work together, it tells them apart. It is not a password.': 'Créé pour vous maintenant et conservé. Si deux personnes portant le même nom travaillent ensemble, il les distingue. Ce n’est pas un mot de passe.',
  'Made for you the first time the app started and kept. It tells two people with the same name apart when you work on a note together. It is not a password.': 'Créé pour vous la première fois que l’application a démarré, et conservé. Il distingue deux personnes portant le même nom quand vous travaillez ensemble sur une note. Ce n’est pas un mot de passe.',
  'Make flashcards from a document with the assistant, and learn them. Needs the assistant.': 'Créer des cartes mémoire à partir d’un document avec l’assistant, et les apprendre. Nécessite l’assistant.',
  'Mathematics and physics': 'Mathématiques et physique',
  'Maths': 'Maths',
  'Next': 'Suivant',
  'Notes you write and draw, PDFs you annotate, and notes you work on together with others.': 'Les notes que vous écrivez et dessinez, les PDF que vous annotez, et les notes que vous travaillez à plusieurs.',
  'Only the basics': 'Seulement l’essentiel',
  'Organising and sharing': 'Organisation et partage',
  'Other people see this name when you work on a note together, and it goes on what you add to a note, so the history can show who wrote what.': 'Les autres voient ce nom quand vous travaillez ensemble sur une note, et il accompagne ce que vous ajoutez à une note, pour que l’historique indique qui a écrit quoi.',
  'PDF': 'PDF',
  'Philosophy, history and literature': 'Philosophie, histoire et littérature',
  'Pictures': 'Images',
  'Plots': 'Graphiques',
  'Put pictures on a page.': 'Placer des images sur une page.',
  'Reading and looking things up': 'Lire et chercher des informations',
  'Reading texts closely, quoting and arguing in writing.': 'Lire des textes en détail, citer et argumenter par écrit.',
  'Rules that sort, title and file notes by themselves.': 'Des règles qui trient, titrent et classent les notes toutes seules.',
  'Save a note as a file (.uninote) and open one.': 'Enregistrer une note comme fichier (.uninote) et en ouvrir une.',
  'Search the web, Wikipedia and translate from selected text, with the page beside the note.': 'Chercher sur le web, Wikipédia et traduire à partir du texte sélectionné, avec la page à côté de la note.',
  'Select, move, copy and delete drawings, text boxes and pictures by drawing around them.': 'Sélectionner, déplacer, copier et supprimer des dessins, zones de texte et images en les entourant.',
  'Set up for what you use the app for:': 'Configuration selon ce pour quoi vous utilisez l’application :',
  'Shapes': 'Formes',
  'Sharing notes and writing them together.': 'Partager des notes et les écrire à plusieurs.',
  'Show everything': 'Tout afficher',
  'Show me everything': 'Tout me montrer',
  'Show the intro again': 'Revoir la présentation',
  'Sketches, pictures and layouts.': 'Croquis, images et mises en page.',
  'Skip': 'Passer',
  'Every tool is on.': 'Tous les outils sont activés.',
  'Nothing chosen: you start with the basics. More tools can be switched on in the settings at any time.': 'Rien de choisi : vous commencez avec l’essentiel. D’autres outils peuvent être activés dans les réglages à tout moment.',
  'Everyday notes and meetings': 'Notes du quotidien et réunions',
  'Lists, meeting notes, to-dos and things to remember.': 'Listes, notes de réunion, tâches et choses à retenir.',
  'Everyday': 'Quotidien',
  'Straight lines and shapes': 'Lignes droites et formes',
  'Switch off what you do not use and it goes away from the screens. Nothing is deleted: notes that use a tool that is off stay as they are.': 'Désactivez ce que vous n’utilisez pas et cela disparaît des écrans. Rien n’est supprimé : les notes qui utilisent un outil désactivé restent telles quelles.',
  'Tables': 'Tableaux',
  'Tables in text boxes and in the written document.': 'Tableaux dans les zones de texte et dans le document écrit.',
  'The calendar, the week view, tasks and syncing them.': 'L’agenda, la vue semaine, les tâches et leur synchronisation.',
  'The name other people see in live sessions, on what you add to a note, and in the history of a note.': 'Le nom que les autres voient dans les sessions en direct, sur ce que vous ajoutez à une note, et dans l’historique d’une note.',
  'Their id: {id}': 'Leur identifiant : {id}',
  'Theme images': 'Images de thème',
  'Three quick questions make it fit you: what to call you, what you use it for, and which tools you want to see. You can change all of it later in the settings.': 'Trois questions rapides pour l’adapter à vous : comment vous appeler, à quoi vous l’utilisez, et quels outils vous voulez voir. Vous pourrez tout changer plus tard dans les réglages.',
  'Tools': 'Outils',
  'Turn a handwritten formula into LaTeX (needs the model from the settings).': 'Convertir une formule manuscrite en LaTeX (nécessite le modèle des réglages).',
  'Turn handwriting into text (needs the model from the settings).': 'Convertir l’écriture manuscrite en texte (nécessite le modèle des réglages).',
  'Unnamed': 'Sans nom',
  'Vocabulary, grammar and texts in more than one language.': 'Vocabulaire, grammaire et textes en plusieurs langues.',
  'Welcome to Notation': 'Bienvenue dans Notation',
  'What should we call you?': 'Comment devons-nous vous appeler ?',
  'What will you use Notation for?': 'À quoi utiliserez-vous Notation ?',
  'Working together': 'Travail à plusieurs',
  'Working with others': 'Travailler avec d’autres',
  'Writing and drawing': 'Écrire et dessiner',
  'Creative tools': 'Outils de création',
  'More brushes': 'Plus de pinceaux',
  'Pencil, fountain pen, calligraphy nib, marker, charcoal, airbrush and watercolour for the drawing bar.': 'Crayon, stylo-plume, plume de calligraphie, marqueur, fusain, aérographe et aquarelle pour la barre de dessin.',
  'Symmetry drawing': 'Dessin en symétrie',
  'Draw with a mirror or around a centre: what you draw is repeated on the other side or in turns (mandalas, patterns).': 'Dessiner avec un miroir ou autour d’un centre : ce que vous dessinez est répété de l’autre côté ou en rotation (mandalas, motifs).',
  'Line stabiliser': 'Stabilisateur de trait',
  'Smooths a shaky hand: the line follows the pen with a little delay, for clean lettering and line art.': 'Lisse une main qui tremble : le trait suit le stylo avec un léger retard, pour une belle calligraphie et des dessins au trait.',
  'Pencil': 'Crayon',
  'Fountain pen': 'Stylo-plume',
  'Calligraphy': 'Calligraphie',
  'Marker': 'Marqueur',
