  'Off': 'Désactivé',
  'Light': 'Léger',
  'Medium': 'Moyen',
  'Strong': 'Fort',
  'Symmetry: {kind}': 'Symétrie : {kind}',
  'Mirror left and right': 'Miroir gauche et droite',
  'Mirror up and down': 'Miroir haut et bas',
  'Mirror both ways': 'Miroir dans les deux sens',
  'Around the centre': 'Autour du centre',
  'Around the centre, mirrored': 'Autour du centre, en miroir',
  '{n} turns': '{n} tours',
  'You': 'Vous',
  'You can leave the name empty and set it later.': 'Vous pouvez laisser le nom vide et le définir plus tard.',
  'Your id: {id}': 'Votre identifiant : {id}',
  'Your name': 'Votre nom',
  'Your tools': 'Vos outils',
  'Smart features': 'Fonctions intelligentes',
  'Everything on these pages was made by the app. Write on it, change it, delete it: it is only here to try things on.': 'Tout ce qui se trouve sur ces pages a été créé par l’application. Écrivez dessus, modifiez-le, supprimez-le : elles servent seulement à essayer.',
  'Everything in this note was made by the app. Write on it, change it, delete it: it is only here to try things on.': 'Tout ce qui se trouve dans cette note a été créé par l’application. Écrivez dessus, modifiez-le, supprimez-le : elle sert seulement à essayer.',
  'Write like a document': 'Écrire comme un document',
  'This page is a written document: **bold**, *italic*, `code` and ==highlights== are just Markdown, and the bar at the side formats the text for you. Headings, the table of contents above, tables, pictures and footnotes[^1] all work, and it prints as pages.': 'Cette page est un document écrit : **gras**, *italique*, `code` et ==surlignages== sont du Markdown, et la barre latérale met le texte en forme pour vous. Titres, table des matières ci-dessus, tableaux, images et notes de bas de page[^1] fonctionnent, et l’ensemble s’imprime en pages.',
  'Pick the pen in the drawing bar and write anywhere, with a stylus or a finger. Draw a ring round something with the lasso to move, copy or delete it. A note can hold both: the written document first, then pages to draw on.': 'Choisissez le stylo dans la barre de dessin et écrivez n’importe où, avec un stylet ou un doigt. Tracez un cercle autour d’un élément avec le lasso pour le déplacer, le copier ou le supprimer. Une note peut contenir les deux : d’abord le document écrit, puis des pages à dessiner.',
  'A mind map, a state machine, a search tree and a graph with its shortest ways: drawn from text, on the next page. The facts under each were worked out by the app.': 'Une carte mentale, une machine à états, un arbre de recherche et un graphe avec ses plus courts chemins : dessinés à partir de texte, sur la page suivante. Les faits sous chacun ont été calculés par l’application.',
  'Like this one. The next page is a notebook page: draw on it.': 'Comme celle-ci. La page suivante est une page de cahier : dessinez dessus.',
  'Write and draw': 'Écrire et dessiner',
  'Pen and highlighter': 'Stylo et surligneur',
  'Lasso and layers': 'Lasso et calques',
  'Check my working': 'Vérifier mon raisonnement',
  'Solve and plot': 'Résoudre et tracer',
  'Diagrams': 'Schémas',
  'Mind maps': 'Cartes mentales',
  'Automata, trees, graphs': 'Automates, arbres, graphes',
  'Together': 'À plusieurs',
  'Live sessions': 'Sessions en direct',
  'A mind map, made from a list with the diagram button.': 'Une carte mentale, faite à partir d’une liste avec le bouton schéma.',
  'Pick the pen in the drawing bar and write anywhere, with a stylus or a finger. Draw a ring round something with the lasso to move, copy or delete it. Double-tap the page (triple-click on a computer) to add a text box like this one.': 'Choisissez le stylo dans la barre de dessin et écrivez n’importe où, avec un stylet ou un doigt. Tracez un cercle autour d’un élément avec le lasso pour le déplacer, le copier ou le supprimer. Double-tapez la page (triple-clic sur un ordinateur) pour ajouter une zone de texte comme celle-ci.',
  'Write a worked solution by hand. A moment later each line gets a green check or a red cross; tap it to see what was checked. Like this:': 'Écrivez une solution détaillée à la main. Un instant plus tard, chaque ligne reçoit une coche verte ou une croix rouge ; touchez-la pour voir ce qui a été vérifié. Comme ceci :',
  'End a calculation with = and the result appears:': 'Terminez un calcul par = et le résultat apparaît :',
  'true in every row': 'vrai dans chaque ligne',
  'false in every row': 'faux dans chaque ligne',
  'true in {n} of {rows} rows': 'vrai dans {n} lignes sur {rows}',
  'Truth tables': 'Tables de vérité',
  'The grid button makes the truth table of a formula, with a column for every part of it. This is (p ∧ q) → r:': 'Le bouton grille crée la table de vérité d’une formule, avec une colonne pour chaque partie. Voici (p ∧ q) → r :',
  'Diagrams from a few lines of text': 'Schémas à partir de quelques lignes de texte',
  'A state machine, a search tree and a graph with its shortest ways, drawn from text. The facts under each were worked out by the app.': 'Une machine à états, un arbre de recherche et un graphe avec ses plus courts chemins, dessinés à partir de texte. Les faits sous chacun ont été calculés par l’application.',
  'Flashcards from your notes and your mistakes': 'Cartes mémoire à partir de vos notes et de vos erreurs',
  'Citations with [@key] and a list of sources': 'Citations avec [@clé] et liste des sources',
  'PDFs to write on, and notes as PDF': 'PDF où écrire, et notes en PDF',
  'A calendar and tasks': 'Un agenda et des tâches',
  'Notes written together, live': 'Notes écrites à plusieurs, en direct',
  'And more': 'Et plus encore',
  'The settings hold the tools you can switch on and off, the models to download and the switch for all the AI features.': 'Les réglages contiennent les outils que vous pouvez activer ou désactiver, les modèles à télécharger et l’interrupteur de toutes les fonctions d’IA.',
  'Language, colour and pen': 'Langue, couleur et stylo',
  'All of this can be changed later in the settings.': 'Tout cela peut être modifié plus tard dans les réglages.',
  'Try your pen': 'Essayez votre stylo',
  'Write or draw in the box with the pen, a finger or the mouse.': 'Écrivez ou dessinez dans la case avec le stylo, un doigt ou la souris.',
  'What a finger does': 'Ce que fait un doigt',
  'A pen was found, and it tells how hard it presses.': 'Un stylo a été détecté, et il indique la pression exercée.',
  'A pen was found.': 'Un stylo a été détecté.',
  'A finger was found. If you have a pen, try it too.': 'Un doigt a été détecté. Si vous avez un stylo, essayez-le aussi.',
  'A mouse was found.': 'Une souris a été détectée.',
  'Where your notes live': 'Où vivent vos notes',
  'Your notes are kept on this device, in the app. Nothing is sent anywhere unless you set it up.': 'Vos notes sont conservées sur cet appareil, dans l’application. Rien n’est envoyé ailleurs, sauf si vous le configurez.',
  'Use it on more than one device?': 'Vous l’utilisez sur plusieurs appareils ?',
  'Link this device with your others to keep the notes, folders and settings the same on all of them.': 'Reliez cet appareil à vos autres appareils pour garder les mêmes notes, dossiers et réglages sur tous.',
  'Set up syncing': 'Configurer la synchronisation',
  'Syncing': 'Synchronisation',
  'Not now is fine: it is in the settings whenever you want it.': 'Plus tard, c’est bien : c’est dans les réglages quand vous voulez.',
  'The download of "{name}" did not work. You can try again in the settings.': 'Le téléchargement de « {name} » n’a pas fonctionné. Vous pouvez réessayer dans les réglages.',
  'You can carry on: the download continues in the background.': 'Vous pouvez continuer : le téléchargement se poursuit en arrière-plan.',
  '**Welcome to Notation**\nThis page shows what you can do. You can write on it, change it or delete it: it is only here to try things on.': '**Bienvenue dans Notation**\nCette page montre ce que vous pouvez faire. Vous pouvez écrire dessus, la modifier ou la supprimer : elle sert seulement à essayer.',
  '**Write and draw**\nPick the pen in the drawing bar and write anywhere on the page, with a stylus or a finger. Draw a ring round something with the lasso to move, copy or delete it. Double-tap the page (triple-click on a computer) to add a text box like this one.': '**Écrire et dessiner**\nChoisissez le stylo dans la barre de dessin et écrivez n’importe où sur la page, avec un stylet ou un doigt. Tracez un cercle autour d’un élément avec le lasso pour le déplacer, le copier ou le supprimer. Double-tapez la page (triple-clic sur un ordinateur) pour ajouter une zone de texte comme celle-ci.',
  '**Tables and truth tables**\nThe table button in the insert bar makes a table. The grid button next to it makes the truth table of a formula, like this one for p → q:': '**Tableaux et tables de vérité**\nLe bouton tableau de la barre d’insertion crée un tableau. Le bouton grille à côté crée la table de vérité d’une formule, comme celle-ci pour p → q :',
  '**Mind maps and diagrams**\nThe diagram button turns an outline, or lines such as Start -> Check -> Done, into a mind map or a flowchart. In advanced mode it draws a state machine, a tree or a graph from a text and tells you what is true about it.': '**Cartes mentales et schémas**\nLe bouton schéma transforme un plan, ou des lignes comme Début -> Vérifier -> Terminé, en carte mentale ou organigramme. En mode avancé, il dessine une machine à états, un arbre ou un graphe à partir d’un texte et indique ce qui est vrai à son sujet.',
  '**Maths**\nWrite a calculation by hand and end it with = to see the result. With "Check my maths" on, each line of a worked solution gets a green check or a red cross a moment after you write it; tap the mark to see what was checked and to correct what was read. This needs the formula model from the settings.': '**Maths**\nÉcrivez un calcul à la main et terminez-le par = pour voir le résultat. Avec « Vérifier mes maths » activé, chaque ligne d’une solution détaillée reçoit une coche verte ou une croix rouge peu après l’écriture ; touchez la marque pour voir ce qui a été vérifié et corriger ce qui a été mal lu. Cela nécessite le modèle de formules des réglages.',
  '**Handwriting to text**\nSelect some handwriting to turn it into text. This needs the handwriting model from the settings.': '**Écriture manuscrite en texte**\nSélectionnez de l’écriture manuscrite pour la convertir en texte. Cela nécessite le modèle d’écriture manuscrite des réglages.',
  '**Where to go from here**\nThe settings hold the tools you can switch on and off, the models to download and the switch for all the AI features. Every tool in the bar has a tip when you hold the pointer over it or press and hold.': '**Pour la suite**\nLes réglages contiennent les outils que vous pouvez activer ou désactiver, les modèles à télécharger et l’interrupteur de toutes les fonctions d’IA. Chaque outil de la barre a une info-bulle quand vous placez le pointeur dessus ou appuyez longuement.',
  'Make a note that shows the tools': 'Créer une note qui montre les outils',
  'One page, with the tools you chose on it, to try them on. You can delete it.': 'Une page, avec les outils que vous avez choisis, pour les essayer. Vous pouvez la supprimer.',
  'Reading your handwriting, checking your maths and the assistant run on this device. Each needs a model that is downloaded once.': 'La lecture de votre écriture, la vérification de vos calculs et l’assistant fonctionnent sur cet appareil. Chacun nécessite un modèle à télécharger une seule fois.',
  'Turn this off and no AI feature is offered and nothing is downloaded. You can turn it on later in the settings.': 'Désactivez-les et aucune fonction d’IA n’est proposée ni aucun téléchargement effectué. Vous pourrez les réactiver plus tard dans les réglages.',
  'Already on this device': 'Déjà sur cet appareil',
  '{description} About {size} MB.': '{description} Environ {size} Mo.',
  'Nothing will be downloaded.': 'Rien ne sera téléchargé.',
  'Pressing Start downloads {size} MB in the background; the settings show how far it is.': 'Appuyer sur Démarrer télécharge {size} Mo en arrière-plan ; les réglages indiquent où en est le téléchargement.',
  'Turns what you write by hand into text, to search and copy.': 'Transforme ce que vous écrivez à la main en texte, pour chercher et copier.',
  'Formulas and maths check': 'Formules et vérification des calculs',
  'Reads handwritten formulas and marks your working line by line.': 'Lit les formules manuscrites et vérifie votre raisonnement ligne par ligne.',
  'Answers questions about a note and summarises it. A big download, so it is only on if you tick it.': 'Répond aux questions sur une note et la résume. Gros téléchargement, donc activé seulement si vous le cochez.',
  'Duplicate drawing': 'Dupliquer le dessin',
  'Duplicate the selection': 'Dupliquer la sélection',
  'Duplicate text box': 'Dupliquer la zone de texte',
  'Duplicate picture': 'Dupliquer l’image',
  'Read the writing and formulas ahead of time, so converting them is instant': 'Lire à l’avance l’écriture et les formules, pour les convertir instantanément',
  'Reads the handwriting ahead of time': 'Lit l’écriture manuscrite à l’avance',
  'Reads the formulas ahead of time': 'Lit les formules à l’avance',
  'Reads the handwriting and the formulas ahead of time': 'Lit l’écriture manuscrite et les formules à l’avance',
  'The handwriting and formula readers are switched off (see Settings)': 'Les lecteurs d’écriture et de formules sont désactivés (voir les réglages)',
  'The models are not installed (see Settings)': 'Les modèles ne sont pas installés (voir les réglages)',
  'Check my maths': 'Vérifier mes maths',
  'Marks the maths you write as right or wrong, line by line, a moment after you wrote it, and gives the result of a line that ends with =. Needs the formula model from the settings.': 'Marque vos calculs comme justes ou faux, ligne par ligne, peu après les avoir écrits, et donne le résultat d’une ligne qui se termine par =. Nécessite le modèle de formules des réglages.',
  'This looks right': 'Ça semble juste',
  'Right, up to rounding': 'Juste, à l’arrondi près',
  'The sum does not work out': 'La somme ne tombe pas juste',
  'The two sides are not equal': 'Les deux membres ne sont pas égaux',
  'That is not the derivative': 'Ce n’est pas la dérivée',
  'That is not the integral': 'Ce n’est pas l’intégrale',
  'That is not the limit': 'Ce n’est pas la limite',
  'That does not solve the line above': 'Cela ne résout pas la ligne au-dessus',
  'This does not follow from the line above': 'Cela ne découle pas de la ligne au-dessus',
  'A solution of the line above is lost': 'Une solution de la ligne au-dessus est perdue',
  'This lets in a solution the line above did not have': 'Cela fait apparaître une solution que la ligne au-dessus n’avait pas',
  'I read:': 'J’ai lu :',
  'For example:': 'Par exemple :',
  'It works out to:': 'Cela donne :',
  'The solution that is missing:': 'La solution manquante :',
  'The solution that is new:': 'La solution nouvelle :',
  'The line above has:': 'La ligne au-dessus a :',
  'It should be:': 'Cela devrait être :',
  'Checked by working it out in numbers on this device. If the writing was read wrongly, the check is wrong too.': 'Vérifié en calculant avec des nombres sur cet appareil. Si l’écriture a été mal lue, la vérification l’est aussi.',
  'The formula model is not installed (see Settings)': 'Le modèle de formules n’est pas installé (voir les réglages)',
  'Checking...': 'Vérification...',
  'A line could not be read': 'Une ligne n’a pas pu être lue',
  'Nothing to check in this line': 'Rien à vérifier dans cette ligne',
  'Check the maths in the selection': 'Vérifier les maths de la sélection',
  'Spell checking': 'Correction orthographique',
  'Underlines misspelled words in text boxes, the written document and (once read) handwriting, with suggestions. Needs a dictionary from the settings.': 'Souligne les mots mal orthographiés dans les zones de texte, le document écrit et l’écriture (une fois lue), avec des suggestions. Nécessite un dictionnaire dans les réglages.',
  'Misspelled words get a wavy red line in text boxes and the written document; tap one for suggestions. A word is right if the dictionary of any language that is on takes it, so a note in two languages works. The dictionaries are the Hunspell dictionaries of the LibreOffice project, downloaded when you turn a language on (they are not part of the app and have licences of their own). Everything is checked on this device.': 'Les mots mal orthographiés reçoivent un trait rouge ondulé dans les zones de texte et le document écrit ; touchez-en un pour des suggestions. Un mot est juste si le dictionnaire de l’une des langues activées l’accepte, donc une note en deux langues fonctionne. Les dictionnaires sont les dictionnaires Hunspell du projet LibreOffice, téléchargés quand vous activez une langue (ils ne font pas partie de l’application et ont leurs propres licences). Tout est vérifié sur cet appareil.',
  'Your own words': 'Vos propres mots',
  'Add a word': 'Ajouter un mot',
  'Download about {size} MB': 'Télécharger environ {size} Mo',
  'Licence: {licence}': 'Licence : {licence}',
  'see the README': 'voir le README',
  'Delete the dictionary': 'Supprimer le dictionnaire',
  'Licence and README': 'Licence et README',
  'Add to dictionary': 'Ajouter au dictionnaire',
  'Ignore': 'Ignorer',
