  'Copied: {word}': 'Copié : {word}',
  'Read as: {word}': 'Lu comme : {word}',
  'Mark words that are spelled right': 'Marquer les mots bien orthographiés',
  'In handwriting, a green dotted line under each word that was read and found right (tap it to see what it was read as), to check that your writing was taken for writing.': 'Dans l’écriture manuscrite, un trait vert en pointillés sous chaque mot lu et jugé juste (touchez-le pour voir comment il a été lu), pour vérifier que votre écriture a bien été prise pour de l’écriture.',
  'This does not hold for:': 'Ceci ne vaut pas pour :',
  'This is not true': 'Ce n’est pas vrai',
  'These matrices are not equal': 'Ces matrices ne sont pas égales',
