  'The sizes are:': 'Les dimensions sont :',
  'The units do not fit': 'Les unités ne correspondent pas',
  'I am not sure I read this right': 'Je ne suis pas sûr d’avoir bien lu ceci',
  'As I read it, this is a mistake, but the writing can be read another way (below). Pick what you wrote:': 'Tel que je le lis, c’est une erreur, mais l’écriture peut se lire autrement (ci-dessous). Choisissez ce que vous avez écrit :',
  'Or did you write:': 'Ou bien avez-vous écrit :',
