  'The units are:': 'Les unités sont :',
  'Its determinant:': 'Son déterminant :',
  'They differ at:': 'Ils diffèrent en :',
  'I read (correct it if it is wrong):': 'J’ai lu (corrigez si c’est faux) :',
  'Checked by working it out in numbers on this device. If the writing was read wrongly, correct it above: the check is done again.': 'Vérifié en calculant avec des nombres sur cet appareil. Si l’écriture a été mal lue, corrigez-la ci-dessus : la vérification est refaite.',
  'Suggestions are put in order with a list of the most common words of the language (FrequencyWords by Hermit Dave, from film and television subtitles, licence CC BY-SA 4.0), downloaded with the dictionary.': 'Les suggestions sont classées avec une liste des mots les plus courants de la langue (FrequencyWords de Hermit Dave, issus des sous-titres de films et de séries, licence CC BY-SA 4.0), téléchargée avec le dictionnaire.',
  'General': 'Général',
  'Tools and writing': 'Outils et écriture',
  'AI and models': 'IA et modèles',
  'Sync and sharing': 'Synchronisation et partage',
  'A Nextcloud calendar is connected in the settings under Sync and sharing, with the other services.': 'Un agenda Nextcloud est connecté dans les réglages, sous Synchronisation et partage, avec les autres services.',
  'Extensions': 'Extensions',
  'Extensions are small scripts (JavaScript) that add tools to the menu of selected text and actions to the automations. Each runs in a sandbox: it cannot reach your files, the network or your notes unless you give it that permission, it is stopped if it runs too long or uses too much memory, and it is off until you switch it on. Only install extensions from people you trust.': 'Les extensions sont de petits scripts (JavaScript) qui ajoutent des outils au menu du texte sélectionné et des actions aux automatisations. Chacune tourne dans un bac à sable : elle ne peut atteindre ni vos fichiers, ni le réseau, ni vos notes sans que vous lui en donniez l’autorisation ; elle est arrêtée si elle tourne trop longtemps ou utilise trop de mémoire, et elle reste désactivée tant que vous ne l’activez pas. N’installez que des extensions de personnes en qui vous avez confiance.',
  'Install from a file (.zip)': 'Installer depuis un fichier (.zip)',
  'Write one': 'En écrire une',
  'Write an extension': 'Écrire une extension',
  'The manifest says what it is called, what it adds and what it asks to be allowed to do (JSON):': 'Le manifeste indique son nom, ce qu’elle ajoute et ce qu’elle demande à pouvoir faire (JSON) :',
  'The script (JavaScript):': 'Le script (JavaScript) :',
  'Install': 'Installer',
  'No extensions yet.': 'Aucune extension pour l’instant.',
  'The script engine is not available on this device: extensions cannot run.': 'Le moteur de scripts n’est pas disponible sur cet appareil : les extensions ne peuvent pas fonctionner.',
  'Extensions do not run in the browser: a script there could reach your notes, as the browser cannot keep it apart from them. Use the app on a computer or phone for them.': 'Les extensions ne fonctionnent pas dans le navigateur : un script y pourrait atteindre vos notes, le navigateur ne pouvant pas le tenir à distance de celles-ci. Utilisez l’application sur un ordinateur ou un téléphone pour cela.',
  'Could not install it: {error}': 'Impossible de l’installer : {error}',
  'Installed {name}. It is off until you switch it on.': '{name} installée. Elle est désactivée tant que vous ne l’activez pas.',
  'It asks to be allowed to:': 'Elle demande à pouvoir :',
  'Nothing: it only works on the text it is given.': 'Rien : elle agit seulement sur le texte qu’on lui donne.',
  'Actions': 'Actions',
  '{name}: {error}': '{name} : {error}',
  'The text changed meanwhile: the result was not put in': 'Le texte a changé entre-temps : le résultat n’a pas été inséré',
