  'An extension action that is not installed': 'Une action d’extension qui n’est pas installée',
  'No extension has an action to run. Install one in Settings > Extensions and switch it on.': 'Aucune extension n’a d’action à lancer. Installez-en une dans Réglages > Extensions et activez-la.',
  'Runs an action of an extension, with the permissions you gave it. What it returns is shown as the result of the automation.': 'Lance une action d’une extension, avec les autorisations que vous lui avez données. Ce qu’elle renvoie est affiché comme résultat de l’automatisation.',
  'Choose an action': 'Choisir une action',
  'Reading the writing ahead of time while the note is open': 'Lecture de l’écriture à l’avance pendant que la note est ouverte',
  'While the note is open, the pen strokes that lie close together are grouped and, after things have been quiet for a moment (never while you draw), read in the background. When you then select that writing and convert it, the result is there at once. Needs the models from Settings. Nothing is changed in the note.': 'Pendant que la note est ouverte, les tracés à la plume qui sont proches les uns des autres sont regroupés et, une fois que tout est calme un moment (jamais pendant que vous dessinez), lus en arrière-plan. Quand vous sélectionnez ensuite cette écriture et la convertissez, le résultat est déjà là. Nécessite les modèles des réglages. Rien n’est modifié dans la note.',
