  'Puts what the writing says under it, out of sight, so that a PDF viewer can select, copy and search it. What was not read yet is read while the PDF is made (up to a minute).': 'Place sous l’écriture ce qu’elle dit, hors de vue, pour qu’un lecteur de PDF puisse la sélectionner, la copier et la chercher. Ce qui n’a pas encore été lu l’est pendant la création du PDF (jusqu’à une minute).',
