  'For a stylus on a tablet or a screen that has one. A pen that cannot tell how hard it presses draws lines of one thickness.': 'Pour un stylet sur une tablette ou un écran qui en a un. Un stylo qui ne sait pas mesurer la pression trace des lignes d’une seule épaisseur.',
  'Thicker lines where the pen presses harder': 'Lignes plus épaisses là où le stylo appuie plus fort',
  'Sensitivity': 'Sensibilité',
  'Fewer tools': 'Moins d’outils',
  'More tools: guides, stabiliser, symmetry, onion skin, straightening, clear the page': 'Plus d’outils : repères, stabilisateur, symétrie, papier calque, redressement, vider la page',
  'Export with layers (OpenRaster, for Krita or GIMP)': 'Exporter avec les calques (OpenRaster, pour Krita ou GIMP)',
  'Response': 'Réponse',
  'Soft: a light touch already gives a thick line. Firm: it takes a hard press.': 'Souple : un toucher léger donne déjà un trait épais. Ferme : il faut appuyer fort.',
  'Tilt thickens': 'L’inclinaison épaissit',
  'A pen that reports how far it leans draws thicker lines when held flat, like the side of a pencil.': 'Un stylo qui indique son inclinaison trace des lignes plus épaisses quand il est tenu à plat, comme le côté d’un crayon.',
  'Button on the side of the pen (held down)': 'Bouton sur le côté du stylo (maintenu enfoncé)',
  'A finger': 'Un doigt',
  'Once the pen has been used, fingers only scroll and zoom, so that a resting hand does not write.': 'Une fois le stylo utilisé, les doigts ne font que défiler et zoomer, pour qu’une main posée n’écrive pas.',
  'Fingers never write; only the pen (or a mouse) does.': 'Les doigts n’écrivent jamais ; seul le stylo (ou une souris) écrit.',
  'Fingers write too, also when a pen is in use.': 'Les doigts écrivent aussi, même quand un stylo est utilisé.',
  'Show a ring where the pen hovers': 'Afficher un anneau là où le stylo survole',
  'As big as the line it would draw.': 'Aussi grand que le trait qu’il tracerait.',
