  'Use at least 6 characters.': 'Utilisez au moins 6 caractères.',
  'Use at least 4 characters.': 'Utilisez au moins 4 caractères.',
  'The two entries are not the same.': 'Les deux saisies ne sont pas identiques.',
  'Keeps the note out of sight: its title is hidden and it asks for the passcode to open. The content is stored as usual, so this does not protect against someone who reads the files of the app.': 'Tient la note hors de vue : son titre est masqué et elle demande le code d’accès pour s’ouvrir. Le contenu est stocké comme d’habitude, donc cela ne protège pas contre quelqu’un qui lit les fichiers de l’application.',
  'Encrypts the whole note, its title too, with a passphrase. Nothing of it is stored in plain, except while it is open. If you forget the passphrase, the note is lost for good.': 'Chiffre toute la note, son titre compris, avec une phrase secrète. Rien n’en est stocké en clair, sauf pendant qu’elle est ouverte. Si vous oubliez la phrase secrète, la note est perdue à jamais.',
