  'Ask your notes': 'Interroger vos notes',
  'Ask anything: the notes that fit your question are found first, then the passages in them that answer it.': 'Demandez ce que vous voulez : les notes qui correspondent à votre question sont trouvées d’abord, puis les passages qui y répondent.',
  'What did I write about deadlines?': 'Qu’ai-je écrit sur les échéances ?',
  'Summarize my latest notes': 'Résume mes dernières notes',
