  'There is nothing to read yet.': 'Il n’y a encore rien à lire.',
  'This device has no speech program (install speech-dispatcher or espeak-ng).': 'Cet appareil n’a pas de programme de synthèse vocale (installez speech-dispatcher ou espeak-ng).',
  'Getting the voice ready... (press to stop)': 'Préparation de la voix... (appuyez pour arrêter)',
  'The speech engine of this device did not take the text (is a voice installed?).': 'Le moteur de synthèse vocale de cet appareil n’a pas pris le texte (une voix est-elle installée ?).',
  'The speech engine of this device did not start (is a voice installed in the system settings?).': 'Le moteur de synthèse vocale de cet appareil n’a pas démarré (une voix est-elle installée dans les réglages système ?).',
  'The speech program made no sound.': 'Le programme de synthèse vocale n’a produit aucun son.',
  'This device has no working speech engine. Install one (for example eSpeak NG or SherpaTTS from F-Droid) and choose it in the system settings under Text-to-speech.': 'Cet appareil n’a pas de moteur de synthèse vocale fonctionnel. Installez-en un (par exemple eSpeak NG ou SherpaTTS depuis F-Droid) et choisissez-le dans les réglages système, à Synthèse vocale.',
  'Summary, presentation, quiz...': 'Résumé, présentation, quiz...',
  'What are the key terms and what do they mean?': 'Quels sont les termes clés et que signifient-ils ?',
  'What is unclear or missing?': 'Qu’est-ce qui n’est pas clair ou manque ?',
  'Make something from this note': 'Créer quelque chose à partir de cette note',
  'It is kept with the note, so it is made only once.': 'C’est conservé avec la note, donc créé une seule fois.',
  'What the AI made of this note, and what it can make': 'Ce que l’IA a tiré de cette note, et ce qu’elle peut en faire',
  'Cards to learn the note by, one question each.': 'Des cartes pour apprendre la note, une question chacune.',
  '{name}: page {n}': '{name} : page {n}',
  'Go to the page': 'Aller à la page',
  'Leave this profile?': 'Quitter ce profil ?',
  'This device stops syncing and forgets the other devices. The notes on it stay. The other devices keep the profile.': 'Cet appareil cesse de se synchroniser et oublie les autres appareils. Les notes qu’il contient restent. Les autres appareils conservent le profil.',
  'Leave this profile': 'Quitter ce profil',
  'Sync profile': 'Profil de synchronisation',
  'Use Notation on several devices as one person: the same id and name, the same notes and folders, the same settings. The devices connect directly to each other; the signalling server only introduces them.': 'Utilisez Notation sur plusieurs appareils comme une seule personne : même identifiant et nom, mêmes notes et dossiers, mêmes réglages. Les appareils se connectent directement entre eux ; le serveur de signalisation ne fait que les présenter.',
  'Add a device': 'Ajouter un appareil',
  'Use a link from another device': 'Utiliser un lien depuis un autre appareil',
  'Name of this device': 'Nom de cet appareil',
  'No other device yet. Add one with a link.': 'Aucun autre appareil pour l’instant. Ajoutez-en un avec un lien.',
  'Syncing...': 'Synchronisation...',
  'Online': 'En ligne',
  'Not online': 'Hors ligne',
  'synced {when}': 'synchronisé {when}',
  'Take this device out of the profile': 'Retirer cet appareil du profil',
  'Looking for your other devices...': 'Recherche de vos autres appareils...',
  'Keep my devices in sync automatically': 'Garder mes appareils synchronisés automatiquement',
  'Done: the device is part of your profile now.': 'Terminé : l’appareil fait maintenant partie de votre profil.',
  'On the other device open Notation, go to Settings → Sync profile → "Use a link from another device" (or the first screen of the app) and enter this link:': 'Sur l’autre appareil, ouvrez Notation, allez dans Réglages → Profil de synchronisation → « Utiliser un lien depuis un autre appareil » (ou sur le premier écran de l’application) et saisissez ce lien :',
  'Notation: add a device': 'Notation : ajouter un appareil',
  'The link holds the secret of your profile: send it only to yourself. It works for ten minutes, and a device in it still has to be let in here.': 'Le lien contient le secret de votre profil : envoyez-le seulement à vous-même. Il fonctionne dix minutes, et un appareil qui l’utilise doit encore être accepté ici.',
  '{name} wants to join your profile': '{name} veut rejoindre votre profil',
  'Is this the code on that device?': 'Est-ce le code affiché sur cet appareil ?',
  'No, that is not my device': 'Non, ce n’est pas mon appareil',
  'Yes, let it in': 'Oui, le laisser entrer',
  'That is not a link to add a device.': 'Ce n’est pas un lien pour ajouter un appareil.',
  'Done: this device is part of the profile now. Its notes, folders and settings are being brought together.': 'Terminé : cet appareil fait maintenant partie du profil. Ses notes, dossiers et réglages sont en cours de fusion.',
  'This code must be the same on the other device:': 'Ce code doit être le même sur l’autre appareil :',
  'If it differs, press Cancel: someone else may be in the way.': 'S’il diffère, appuyez sur Annuler : quelqu’un d’autre se trouve peut-être sur le chemin.',
  'This device takes over the id and name of that profile. Its own notes stay and are brought together with the others.': 'Cet appareil reprend l’identifiant et le nom de ce profil. Ses propres notes sont conservées et fusionnées avec les autres.',
  'Looking for the device that made the link...': 'Recherche de l’appareil qui a créé le lien...',
  'Waiting for the other device to say yes': 'En attente que l’autre appareil dise oui',
  'There is no signalling server: set one in the live collaboration settings.': 'Il n’y a pas de serveur de signalisation : configurez-en un dans les réglages de collaboration en direct.',
  'The device that made the link was not found. Is it online, and is its link still on offer?': 'L’appareil qui a créé le lien est introuvable. Est-il en ligne, et son lien est-il toujours proposé ?',
  'The signalling server could not be reached: {error}': 'Impossible de joindre le serveur de signalisation : {error}',
  'The connection to the other device was lost': 'La connexion à l’autre appareil a été perdue',
  'The other device did not answer': 'L’autre appareil n’a pas répondu',
  'The other device did not follow the protocol': 'L’autre appareil n’a pas suivi le protocole',
  'The other device runs a different version of the sync': 'L’autre appareil utilise une autre version de la synchronisation',
  'The other device did not say who it is': 'L’autre appareil n’a pas dit qui il est',
  'The other devices have another key for this device than the one it signs with, so they refuse it. Sign out of the profile on this device and sign in again.': 'Les autres appareils ont une autre clé pour celui-ci que celle avec laquelle il signe, donc ils le refusent. Déconnectez-vous du profil sur cet appareil, puis reconnectez-vous.',
  'The key of the other device is not the one that was accepted': 'La clé de l’autre appareil n’est pas celle qui a été acceptée',
  'The other device could not prove who it is': 'L’autre appareil n’a pas pu prouver qui il est',
  'Comparing the devices...': 'Comparaison des appareils...',
  'This device was removed from the profile': 'Cet appareil a été retiré du profil',
  'The other device was removed from the profile': 'L’autre appareil a été retiré du profil',
  'Looking at what changed...': 'Examen des changements...',
  'Sending notes...': 'Envoi des notes...',
  'Receiving...': 'Réception...',
  'A new device asks to join': 'Un nouvel appareil demande à rejoindre',
  'You did not let the new device in': 'Vous n’avez pas accepté le nouvel appareil',
  'The other device did not let this one in': 'L’autre appareil n’a pas laissé entrer celui-ci',
  'This device is not one of this profile (add it with the link from a device of the profile)': 'Cet appareil ne fait pas partie de ce profil (ajoutez-le avec le lien d’un appareil du profil)',
  'from before the sync': 'd’avant la synchronisation',
  'The server did not accept this device': 'Le serveur n’a pas accepté cet appareil',
  'No connection could be made to the other device. Networks that block direct connections need a TURN server.': 'Aucune connexion n’a pu être établie avec l’autre appareil. Les réseaux qui bloquent les connexions directes ont besoin d’un serveur TURN.',
  'Already use Notation on another device?': 'Vous utilisez déjà Notation sur un autre appareil ?',
  'Sync this device with it: the same id and name, notes, folders and settings.': 'Synchronisez cet appareil avec lui : même identifiant et nom, notes, dossiers et réglages.',
  'Use a link from that device': 'Utiliser un lien de cet appareil',
  'Online status not known': 'État en ligne inconnu',
  'This device is not in the meeting room, so it cannot see which of your other devices are online. Turn on the automatic sync below, or press "Sync now" on both devices.': 'Cet appareil n’est pas dans la salle de réunion : il ne peut pas voir lesquels de vos autres appareils sont en ligne. Activez la synchronisation automatique ci-dessous, ou appuyez sur « Synchroniser maintenant » sur les deux appareils.',
  'Look for my other devices from time to time': 'Chercher mes autres appareils de temps en temps',
  'When the app starts, when it comes to the front and every ten minutes, this device joins the meeting room for a minute and syncs if another device of yours is there. The server only learns of these short visits. Two devices that both only look from time to time meet only when their visits overlap; one that stays connected is always found.': 'Au démarrage de l’application, quand elle passe au premier plan et toutes les dix minutes, cet appareil rejoint la salle de réunion une minute et se synchronise si un autre de vos appareils s’y trouve. Le serveur ne retient que ces brèves visites. Deux appareils qui ne font que chercher de temps en temps ne se rencontrent que si leurs visites se chevauchent ; un appareil qui reste connecté est toujours trouvé.',
  'If it differs, say so: someone else may be in the way. Nothing of the other device is taken over until you say it is the same.': 'S’il diffère, dites-le : quelqu’un d’autre se trouve peut-être sur le chemin. Rien de l’autre appareil n’est repris tant que vous n’avez pas confirmé qu’il est le même.',
  'It is different': 'Il est différent',
  'It is the same': 'C’est le même',
  'The codes were not the same, so this device was not added': 'Les codes n’étaient pas identiques, donc cet appareil n’a pas été ajouté',
  'The other device did not keep to what it first said': 'L’autre appareil ne s’est pas tenu à ce qu’il avait annoncé d’abord',
  'Stop reading': 'Arrêter la lecture',
  'Read the note aloud': 'Lire la note à voix haute',
  'The event must end after it starts.': 'L’événement doit se terminer après son début.',
  'Notes': 'Notes',
  'Tasks on a calendar': 'Tâches dans un agenda',
  'A task with a day can also be put on a calendar as an all-day event, so that it shows up in the calendar app of the phone or of the server. It goes again when the task is done or deleted.': 'Une tâche avec une date peut aussi être placée dans un agenda sous forme d’événement sur la journée, pour apparaître dans l’application agenda du téléphone ou du serveur. Elle en est retirée quand la tâche est terminée ou supprimée.',
  'There is no calendar to put them on: connect a server or turn on a calendar of the phone first (both must allow writing).': 'Il n’y a pas d’agenda où les mettre : connectez d’abord un serveur ou activez un agenda du téléphone (les deux doivent autoriser l’écriture).',
  'Not on a calendar': 'Pas dans un agenda',
  'Only the tasks that were made by an automation or found in a note': 'Seulement les tâches créées par une automatisation ou trouvées dans une note',
  'What the AI can make of this note': 'Ce que l’IA peut tirer de cette note',
  'Starting...': 'Démarrage...',
  'There is nothing to make a graph of yet: the notes have no text.': 'Il n’y a pas encore de graphe à construire : les notes n’ont pas de texte.',
