  'The graph of facts shows what your notes say, grouped by topic. Making it reads all notes, so it is not made on its own.': 'Le graphe de faits montre ce que disent vos notes, regroupé par thème. Le construire lit toutes les notes, donc il ne se fait pas seul.',
