  'On a device that is already in the profile, go to Settings → Sync profile → "Add a device". Scan the code it shows or paste the link:': 'Sur un appareil déjà dans le profil, allez dans Réglages → Profil de synchronisation → « Ajouter un appareil ». Scannez le code affiché ou collez le lien :',
