  'No cloud account is connected on this device. Connect one (Nextcloud in the settings under Sync and sharing, or S3, Dropbox or OneDrive under sharing), or sync directly with the device that has one.': 'Aucun compte cloud n’est connecté sur cet appareil. Connectez-en un (Nextcloud dans les réglages, sous Synchronisation et partage, ou S3, Dropbox ou OneDrive sous Partage), ou synchronisez directement avec l’appareil qui en a un.',
  'Service': 'Service',
  'not connected': 'non connecté',
  'Folder name': 'Nom du dossier',
  'Every file is sealed with a key from your profile, and the names say nothing. The cloud holds files nobody can read; only your devices can.': 'Chaque fichier est scellé avec une clé de votre profil, et les noms ne disent rien. Le cloud contient des fichiers que personne ne peut lire ; seuls vos appareils le peuvent.',
  'Not encrypted': 'Non chiffré',
  'Notes are normal .uninote files and the list is readable text, so you can open them yourself from the cloud. Anyone who can see the folder can read your notes.': 'Les notes sont des fichiers .uninote ordinaires et la liste est du texte lisible, vous pouvez donc les ouvrir vous-même depuis le cloud. Quiconque peut voir le dossier peut lire vos notes.',
  'Sync through the folder now': 'Synchroniser maintenant via le dossier',
