  'Installed {name}. It is off until you switch it on; then its tools ({tools}) are in the menu of selected text, as "{name}: ...".': '{name} installée. Elle est désactivée tant que vous ne l’activez pas ; ensuite ses outils ({tools}) sont dans le menu du texte sélectionné, sous « {name} : ... ».',
  '{name} is installed and switched on.': '{name} est installée et activée.',
