  'Create with AI': 'Créer avec l’IA',
  'Say what you want in your own words: a tool for selected text, or something that should happen by itself. The AI writes the extension, you read it, and only then is it installed.': 'Dites ce que vous voulez avec vos propres mots : un outil pour le texte sélectionné, ou quelque chose qui doit se produire tout seul. L’IA écrit l’extension, vous la lisez, et seulement ensuite elle est installée.',
  'e.g. A tool that turns the selected lines into a checklist. Or: when a note has not been opened for a month, add a task to look at it.': 'p. ex. Un outil qui transforme les lignes sélectionnées en liste de contrôle. Ou : quand une note n’a pas été ouverte depuis un mois, ajouter une tâche pour la revoir.',
  'What is sent to the AI you chose in Settings: the description of the extension API and your request. No notes, no files. With an AI in the cloud that leaves this device.': 'Ce qui est envoyé à l’IA choisie dans les réglages : la description de l’interface des extensions et votre demande. Ni notes, ni fichiers. Avec une IA dans le cloud, cela quitte cet appareil.',
