  'Remove from the list': 'Retirer de la liste',
  'Shared with people': 'Partagé avec des personnes',
  'Notes and folders you share with people at the same cloud service (Nextcloud), and the ones they share with you. Share from a note (the live button) or from the menu of a folder. What is shared is kept in step in the background. The cloud service can read these files: they are not sealed.': 'Les notes et dossiers que vous partagez avec des personnes du même service cloud (Nextcloud), et ceux qu’elles partagent avec vous. Partagez depuis une note (le bouton en direct) ou depuis le menu d’un dossier. Ce qui est partagé reste à jour en arrière-plan. Le service cloud peut lire ces fichiers : ils ne sont pas scellés.',
  'Shared with': 'Partagé avec',
  'Remove {name}': 'Retirer {name}',
  'Name or address of the person': 'Nom ou adresse de la personne',
  'Connect a cloud service that can share (Nextcloud) in the settings first.': 'Connectez d’abord, dans les réglages, un service cloud capable de partager (Nextcloud).',
  'Where should "{name}" go?': 'Où doit aller « {name} » ?',
  'from {who}': 'de {who}',
  'Nothing is shared yet.': 'Rien n’est encore partagé.',
  'nobody yet': 'personne pour l’instant',
  'from {who} · {role}': 'de {who} · {role}',
  'Ended': 'Terminé',
  'Synced {when}': 'Synchronisé {when}',
  'Share with people...': 'Partager avec des personnes...',
  'That folder is gone': 'Ce dossier n’existe plus',
  'This device is not part of a sync profile yet.': 'Cet appareil ne fait pas encore partie d’un profil de synchronisation.',
  'The share was withdrawn. What you have of it stays.': 'Le partage a été retiré. Ce que vous en avez reste.',
  'The owner removed this. What you have of it stays.': 'Le propriétaire a supprimé cela. Ce que vous en avez reste.',
  'This is not a share from Notation, or from a newer version of it.': 'Ce n’est pas un partage de Notation, ni d’une version plus récente.',
  'You have this {what} already, and not from this share. Delete it here first to take the share in.': 'Vous avez déjà cet élément {what}, et il ne vient pas de ce partage. Supprimez-le d’abord ici pour accepter le partage.',
  'note': 'note',
  'folder': 'dossier',
  'The Nextcloud allows only a few new shares in a short time. Try again in a few minutes.': 'Le Nextcloud n’autorise que quelques nouveaux partages en peu de temps. Réessayez dans quelques minutes.',
  'This Nextcloud does not offer sharing with people.': 'Ce Nextcloud n’offre pas le partage avec des personnes.',
  'The Nextcloud did not share the folder.': 'Le Nextcloud n’a pas pu partager le dossier.',
  'The Nextcloud did not accept the share.': 'Le Nextcloud n’a pas accepté le partage.',
  'Allow sharing with people in the OneDrive settings first (it needs access to all your files).': 'Autorisez d’abord le partage avec des personnes dans les réglages OneDrive (il faut l’accès à tous vos fichiers).',
  'Sign in to OneDrive again, so that it can be allowed to share.': 'Reconnectez-vous à OneDrive, pour qu’il puisse autoriser le partage.',
  'OneDrive does not allow sharing with this person here (an administrator can forbid it for work and school accounts).': 'OneDrive n’autorise pas le partage avec cette personne ici (un administrateur peut l’interdire pour les comptes professionnels et scolaires).',
  'OneDrive says to wait a little. Try again in a few minutes.': 'OneDrive demande d’attendre un peu. Réessayez dans quelques minutes.',
  'The shared folder is not on your OneDrive (any more).': 'Le dossier partagé n’est plus (ou pas) sur votre OneDrive.',
  'Shared with Notation. Open the link in the invitation, or add it in the app: Settings, Sync and sharing.': 'Partagé avec Notation. Ouvrez le lien de l’invitation, ou ajoutez-le dans l’application : Réglages, Synchronisation et partage.',
  'OneDrive did not share the folder.': 'OneDrive n’a pas partagé le dossier.',
  'This is not a link to a share.': 'Ce n’est pas un lien de partage.',
  'This link does not open a shared folder for you. Are you signed in with the account that was invited?': 'Ce lien ne vous ouvre aucun dossier partagé. Êtes-vous connecté avec le compte invité ?',
  'This is not a share from Notation.': 'Ce n’est pas un partage de Notation.',
  'You have this share already.': 'Vous avez déjà ce partage.',
  'Allow sharing with people in the Dropbox settings first (it needs a Dropbox app with access to the whole Dropbox).': 'Autorisez d’abord le partage avec des personnes dans les réglages Dropbox (il faut une application Dropbox avec accès à tout le Dropbox).',
  'Sign in to Dropbox again, so that it can be allowed to share.': 'Reconnectez-vous à Dropbox, pour qu’il puisse autoriser le partage.',
  'Dropbox says to wait a little. Try again in a few minutes.': 'Dropbox demande d’attendre un peu. Réessayez dans quelques minutes.',
  'This Dropbox app is not allowed to share. It has to be registered with access to the whole Dropbox, and with the sharing permissions.': 'Cette application Dropbox n’est pas autorisée à partager. Elle doit être enregistrée avec l’accès à tout le Dropbox, et avec les autorisations de partage.',
  'Your Dropbox e-mail address has to be verified before you can share.': 'Votre adresse e-mail Dropbox doit être vérifiée avant de pouvoir partager.',
  'Your Dropbox plan does not allow sharing with this many people.': 'Votre offre Dropbox ne permet pas de partager avec autant de personnes.',
  'The shared folder is not on your Dropbox (any more).': 'Le dossier partagé n’est plus (ou pas) sur votre Dropbox.',
  'Dropbox did not do it.': 'Dropbox n’a pas effectué l’opération.',
  'Dropbox did not share the folder.': 'Dropbox n’a pas partagé le dossier.',
  'Dropbox is slow to share the folder. Try again in a moment.': 'Dropbox est lent à partager le dossier. Réessayez dans un instant.',
  'Shared with Notation. Accept it in your Dropbox, then it is listed in the app: Settings, Sync and sharing.': 'Partagé avec Notation. Acceptez-le dans votre Dropbox, il apparaît ensuite dans l’application : Réglages, Synchronisation et partage.',
  'Dropbox did not accept the share.': 'Dropbox n’a pas accepté le partage.',
  'Link copied. Send it to {name}: they add it under Settings, Sync and sharing.': 'Lien copié. Envoyez-le à {name} : il l’ajoute dans Réglages, Synchronisation et partage.',
  'Copy the link to send to {name}': 'Copier le lien à envoyer à {name}',
  'A link to a share (OneDrive)': 'Un lien vers un partage (OneDrive)',
  '"{name}" is shared with you by {who}. Take it in under Settings, Sync and sharing.': '« {name} » vous est partagé par {who}. Acceptez-le dans Réglages, Synchronisation et partage.',
  'Also allow sharing with people': 'Autoriser aussi le partage avec des personnes',
  'Sharing a folder with someone, and opening what they share with you, needs access to all your OneDrive files, not just the folder of the app. Changing this signs you out: sign in again afterwards. (Settings, Shared with people)': 'Partager un dossier avec quelqu’un, et ouvrir ce qu’il partage avec vous, nécessite l’accès à tous vos fichiers OneDrive, pas seulement au dossier de l’application. Modifier ce réglage vous déconnecte : reconnectez-vous ensuite. (Réglages, Partagé avec des personnes)',
  'Sharing a folder with someone, and opening what they share with you, only works with a Dropbox app that has access to the whole Dropbox (not the app folder alone), and the sharing permissions. Turn this on only if the app key above is such an app. Changing this signs you out: sign in again afterwards.': 'Partager un dossier avec quelqu’un, et ouvrir ce qu’il partage avec vous, ne fonctionne qu’avec une application Dropbox ayant accès à tout le Dropbox (pas seulement le dossier de l’application), et avec les autorisations de partage. Activez ceci seulement si la clé d’application ci-dessus est une telle application. Modifier ce réglage vous déconnecte : reconnectez-vous ensuite.',
