  'This note has no text boxes or written document to translate. Handwriting is not translated.': 'Cette note n’a ni zone de texte ni document écrit à traduire. L’écriture manuscrite n’est pas traduite.',
  'The text of the PDF is rewritten in its translation, page by page. Longer lines are set smaller, and a line that cannot be shown stays as it was. A version of the note is kept first, and the change can be taken back with Undo.': 'Le texte du PDF est réécrit dans sa traduction, page par page. Les lignes plus longues sont composées plus petites, et une ligne qui ne peut pas être affichée reste telle quelle. Une version de la note est gardée au préalable, et la modification peut être annulée avec Annuler.',
