  'Drawings stay shapes you can edit in a vector program; layers become named groups. Text boxes and pictures are pictures in the file.': 'Les dessins restent des formes modifiables dans un logiciel vectoriel ; les calques deviennent des groupes nommés. Les zones de texte et les images sont des images dans le fichier.',
