  'Alignment lines': 'Lignes d’alignement',
  'Lines that show where a text box, picture or shape you are moving lines up with the others on the page (or the middle and edges of the page), and let it fall into place. Hold Alt to move freely.': 'Les lignes qui montrent où une zone de texte, une image ou une forme que vous déplacez s’aligne avec les autres de la page (ou le milieu et les bords de la page), et la laissent se mettre en place. Maintenez Alt pour déplacer librement.',
