  'like "{text}"': 'comme « {text} »',
  'Connect an AI agent': 'Connecter un agent IA',
  'An AI agent on this computer (Claude Code, an editor with AI, any program that speaks the Model Context Protocol) can then find, read and write your notes, folders, tags and tasks. It connects to this app on this computer only, with the token below. Locked notes are never available to it, and it cannot delete a note for good. Every change to a note keeps a version of it before and after, which you can bring back. What the agent reads goes to the AI service it belongs to: connect only agents you trust with your notes.': 'Un agent IA sur cet ordinateur (Claude Code, un éditeur doté d’IA, tout programme qui parle le protocole Model Context Protocol) peut alors trouver, lire et écrire vos notes, dossiers, étiquettes et tâches. Il se connecte à cette application sur cet ordinateur seulement, avec le jeton ci-dessous. Les notes verrouillées ne lui sont jamais accessibles, et il ne peut pas supprimer définitivement une note. Chaque modification d’une note conserve une version avant et après, que vous pouvez restaurer. Ce que l’agent lit est envoyé au service d’IA auquel il appartient : ne connectez que des agents en qui vous avez confiance.',
