  'The page becomes a source, to cite with [@key]': 'La page devient une source, à citer avec [@clé]',
  'The note is listed on the dashboard, with the question what to do about it': 'La note apparaît sur le tableau de bord, avec la question de ce qu’il faut en faire',
  'The summary is a text box under the rest of the last page': 'Le résumé est une zone de texte sous le reste de la dernière page',
  'The outline is a text box under the rest of the last page': 'Le plan est une zone de texte sous le reste de la dernière page',
  'Only notes without a title are named': 'Seules les notes sans titre sont nommées',
  'About {n} flashcards from the note, kept for review': 'Environ {n} cartes mémoire tirées de la note, gardées pour révision',
  'Half a minute after the last change': 'Une demi-minute après la dernière modification',
  'What this rule did': 'Ce que cette règle a fait',
  'There are no templates here.': 'Il n’y a aucun modèle ici.',
  'Choose a template': 'Choisir un modèle',
  'No template (a blank note)': 'Aucun modèle (une note vierge)',
  'A further step': 'Une étape de plus',
  'Which trigger': 'Quel déclencheur',
  'Bind a key to "Run the automations of trigger 1" in the settings of the shortcuts, or set the side button of the pen to it (Settings, pen)': 'Associez une touche à « Lancer les automatisations du déclencheur 1 » dans les réglages des raccourcis, ou réglez le bouton latéral du stylo dessus (Réglages, stylo)',
  'Minutes before it starts': 'Minutes avant le début',
  'Looked at every minute while the app runs; each event once': 'Vérifié chaque minute pendant que l’application tourne ; chaque événement une seule fois',
  'A note whose title is empty or "Untitled Note" is named after what it says: the language model writes a short title if it is installed (Settings), else the first line is used when it is short enough. A note that has a title is never changed.': 'Une note dont le titre est vide ou « Note sans titre » est nommée d’après son contenu : le modèle de langue écrit un titre court s’il est installé (Réglages), sinon la première ligne est utilisée si elle est assez courte. Une note qui a un titre n’est jamais modifiée.',
  'The assistant reads the text of the note and writes flashcards from it, which are kept for review (Flashcards, spaced repetition). A question that is kept already is not added again. Needs the assistant; a model on this device takes a minute or so.': 'L’assistant lit le texte de la note et en tire des cartes mémoire, qui sont gardées pour révision (Cartes mémoire, répétition espacée). Une question déjà gardée n’est pas ajoutée une seconde fois. Nécessite l’assistant ; un modèle sur cet appareil prend une minute environ.',
  'About how many cards': 'Environ combien de cartes',
  '{n} is how many cards are due. One task a day, today, while there are cards due': '{n} est le nombre de cartes à réviser. Une tâche par jour, aujourd’hui, tant qu’il y a des cartes à réviser',
  'Then also, one after the other': 'Ensuite aussi, l’une après l’autre',
  'Take this step out': 'Retirer cette étape',
  'Add a step': 'Ajouter une étape',
  'The steps run in the background, one after the other. Each can use {result}, what the one before said, in its text; a step that cannot do its work ends the chain.': 'Les étapes s’exécutent en arrière-plan, l’une après l’autre. Chacune peut utiliser {result}, ce que la précédente a dit, dans son texte ; une étape qui ne peut pas faire son travail arrête la chaîne.',
  'Dropbox needs an app of your own: create one at dropbox.com/developers/apps ("Scoped access", "App folder"), allow files.content.write, files.content.read, files.metadata.read and sharing.write, add the redirect URI notation://oauth/dropbox, and enter its app key here.': 'Dropbox a besoin d’une application à vous : créez-en une sur dropbox.com/developers/apps (« Scoped access », « App folder »), autorisez files.content.write, files.content.read, files.metadata.read et sharing.write, ajoutez l’URI de redirection notation://oauth/dropbox, et saisissez ici sa clé d’application.',
  '"{address}" is not the address of a relay. Use something like turn:turn.example.org:3478': '« {address} » n’est pas l’adresse d’un relais. Utilisez quelque chose comme turn:turn.example.org:3478',
  'Notation could not start': 'Notation n’a pas pu démarrer',
  'Nothing was deleted. Close the app and open it again; if this keeps happening, make sure the device has free storage and that this is not an older version of the app than the one that last ran.': 'Rien n’a été supprimé. Fermez l’application et rouvrez-la ; si cela se reproduit, vérifiez que l’appareil a de la place libre et que ce n’est pas une version plus ancienne de l’application que la dernière qui a tourné.',
