  'Change the toolbar profile': 'Changer le profil de barres d’outils',
  'Nothing here. Move a section over from the other bar.': 'Rien ici. Déplacez une section depuis l’autre barre.',
  'Profiles': 'Profils',
  'A profile keeps an arrangement of the toolbars with the tools it uses, so you can change between ways of working (drawing, maths...) in one tap.': 'Un profil garde une disposition des barres d’outils avec les outils qu’il utilise, pour passer d’une façon de travailler à l’autre (dessin, maths...) d’une seule touche.',
  'New profile': 'Nouveau profil',
  'Tools in this profile': 'Outils de ce profil',
  'The tools that are switched on in the settings. One that is off there is off in every profile.': 'Les outils activés dans les réglages. Un outil désactivé là-bas l’est dans tous les profils.',
  '(new)': '(nouveau)',
  'This replaces version {version}.': 'Ceci remplace la version {version}.',
  'It is installed switched off and without any permission. You switch it on and give it these in Settings.': 'Il est installé désactivé et sans aucune autorisation. Vous l’activez et lui donnez celles-ci dans les réglages.',
  'The note was closed': 'La note a été fermée',
  'Could not save the pictures: {error}': 'Impossible d’enregistrer les images : {error}',
  'Saved 1 picture in {dir}': '1 image enregistrée dans {dir}',
  'Saved {n} pictures in {dir}': '{n} images enregistrées dans {dir}',
  '{n} fact': '{n} fait',
  '{n} facts': '{n} faits',
  'Possible contradictions': 'Contradictions possibles',
  'Facts that disagree': 'Faits qui ne concordent pas',
  'These facts come from different notes, are about the same thing and give different numbers. One of them may be out of date, or both may be right in their own place.': 'Ces faits viennent de notes différentes, portent sur la même chose et donnent des chiffres différents. L’un d’eux est peut-être périmé, ou les deux sont justes à leur place.',
  'Says something else in {note}': 'Dit autre chose dans {note}',
  'another note': 'une autre note',
  'Do you use these one at a time?': 'Les utilisez-vous un par un ?',
  'Then give each its own toolbar profile: one tap changes the toolbars to the tools of that use only (drawing without the maths tools, and the other way around). All of them stay available; you can change the profiles whenever you like.': 'Donnez alors à chacun son propre profil de barres d’outils : une touche fait passer les barres aux outils de ce seul usage (dessin sans les outils de maths, et inversement). Tous restent disponibles ; vous pouvez changer les profils quand vous voulez.',
  'Make a profile for each: {names}': 'Créer un profil pour chacun : {names}',
  'Each toolbar profile uses its own share of these tools; what you switch off here is off in all of them.': 'Chaque profil de barres d’outils utilise sa part de ces outils ; ce que vous désactivez ici est désactivé dans tous.',
  'Create': 'Créer',
  'No automation is set for trigger {n} (see Automations)': 'Aucune automatisation n’est définie pour le déclencheur {n} (voir Automatisations)',
  'Trigger {trigger}: ran 1 automation': 'Déclencheur {trigger} : 1 automatisation lancée',
  'Trigger {trigger}: ran {n} automations': 'Déclencheur {trigger} : {n} automatisations lancées',
  'Menu': 'Menu',
  'PDF sharpness': 'Netteté des PDF',
  'The most PDF pages are drawn at. On screen a page is drawn as sharp as the screen shows it, up to this; zoomed in, the part on screen is drawn sharper. Pictures of pages that are exported use it as it is. Higher is sharper but uses more memory and loads slower. Automatic picks 250 dpi on a device with plenty of memory and 200 dpi on others. It applies to PDFs opened from now on.': 'La résolution à laquelle les pages PDF sont dessinées. À l’écran, une page est dessinée aussi nette que l’écran la montre, jusqu’à cette limite ; zoomée, la partie visible est dessinée plus nettement. Les images des pages exportées l’utilisent telle quelle. Plus élevé est plus net mais consomme plus de mémoire et se charge plus lentement. Automatique choisit 250 ppp sur un appareil avec beaucoup de mémoire et 200 ppp sur les autres. Cela s’applique aux PDF ouverts à partir de maintenant.',
  'Automatic ({dpi} dpi on this device)': 'Automatique ({dpi} ppp sur cet appareil)',
  'QR code': 'Code QR',
  'Plan for an exam': 'Plan pour un examen',
  'It could not be looked at.': 'Il n’a pas pu être examiné.',
  'Say what should happen by itself, in your own words. The assistant writes the rule; you look at it, and at what it would have touched, before it is switched on.': 'Dites avec vos mots ce qui doit se passer tout seul. L’assistant écrit la règle ; vous la regardez, ainsi que ce qu’elle toucherait, avant qu’elle ne soit activée.',
  'For example: when I close a note in Physics, give it the tag lecture': 'Par exemple : quand je ferme une note de Physique, lui donner l’étiquette cours',
  'Write the rule': 'Écrire la règle',
  'The assistant could not make a rule of that with what automations can do. Try saying it another way.': 'L’assistant n’a pas pu faire une règle de cela avec ce que les automatisations savent faire. Essayez de le dire autrement.',
  'Looking at what it would touch...': 'Examen de ce qu’elle toucherait...',
  'Added: see the list of automations.': 'Ajoutée : voir la liste des automatisations.',
  'Add, switched off': 'Ajouter, désactivée',
  'Add and switch on': 'Ajouter et activer',
  '{n} line was left out': '{n} ligne a été omise',
  '{n} lines were left out': '{n} lignes ont été omises',
  'Folder': 'Dossier',
  'Relay server (for mobile networks)': 'Serveur relais (pour les réseaux mobiles)',
  'Two devices connect to each other directly. On a mobile network, and behind some other networks, that does not work: a relay (a TURN server) then passes the data between them. It sees nothing of it, as everything is sealed. Run your own (coturn, say) or use a service that offers one, and enter its address and the name and password it gave you. This stays on this device; set it on the devices that are on such a network (it does not hurt on the others).': 'Deux appareils se connectent directement entre eux. Sur un réseau mobile, et derrière certains autres réseaux, cela ne marche pas : un relais (un serveur TURN) fait alors passer les données entre eux. Il n’en voit rien, car tout est scellé. Faites tourner le vôtre (coturn, par exemple) ou utilisez un service qui en propose un, et saisissez son adresse ainsi que le nom et le mot de passe qu’il vous a donnés. Cela reste sur cet appareil ; réglez-le sur les appareils qui sont sur un tel réseau (cela ne gêne pas les autres).',
  'Relay address': 'Adresse du relais',
  'Password': 'Mot de passe',
  'Speech to text': 'Parole en texte',
  'Language spoken': 'Langue parlée',
  'Find out by listening': 'Trouver en écoutant',
  'Record and write down': 'Enregistrer et noter',
  'Use the text': 'Utiliser le texte',
  'Writing down speech needs a model on this device (about {size} MB). It works without the internet, and nothing you say leaves the device.': 'Noter la parole nécessite un modèle sur cet appareil (environ {size} Mo). Cela fonctionne sans Internet, et rien de ce que vous dites ne quitte l’appareil.',
  'New plan': 'Nouveau plan',
  'Say when the exam is. The app works backwards from that day and puts a short session on each day of the calendar, and changes the sessions every day for what you got right.': 'Indiquez la date de l’examen. L’application remonte à partir de ce jour et place une courte session sur chaque jour du calendrier, et modifie chaque jour les sessions selon ce que vous avez bien répondu.',
  'The exam is today': 'L’examen est aujourd’hui',
  '{n} day left: the exam is on {day}': '{n} jour restant : l’examen a lieu le {day}',
  '{n} days left: the exam is on {day}': '{n} jours restants : l’examen a lieu le {day}',
  'No session today': 'Aucune session aujourd’hui',
  '{n} new card does not fit in the time: more minutes a day would help': '{n} nouvelle carte ne rentre pas dans le temps : davantage de minutes par jour aideraient',
  '{n} new cards do not fit in the time: more minutes a day would help': '{n} nouvelles cartes ne rentrent pas dans le temps : davantage de minutes par jour aideraient',
  'Delete the plan and its sessions that are still to come': 'Supprimer le plan et ses sessions à venir',
  'New plan for an exam': 'Nouveau plan pour un examen',
  'What is the exam?': 'Quel est l’examen ?',
  'Biology': 'Biologie',
  'Exam on': 'Examen le',
  'Which cards': 'Quelles cartes',
  'All my cards': 'Toutes mes cartes',
  '{n} minute a day': '{n} minute par jour',
  '{n} minutes a day': '{n} minutes par jour',
  'No session on': 'Aucune session le',
  'Make the plan': 'Créer le plan',
  'Synced': 'Synchronisé',
  'Looking for your other devices. They have to be looking too: press "Sync now" there, or turn on the automatic sync.': 'Recherche de vos autres appareils. Ils doivent chercher aussi : appuyez sur « Synchroniser maintenant » là-bas, ou activez la synchronisation automatique.',
  'Better': 'Meilleur',
  'Faster': 'Plus rapide',
  'Models opened so far': 'Modèles ouverts jusqu’ici',
  'This browser gives the page no graphics card (WebGPU): models run on the processor. WebGPU needs https or localhost, and a browser that has it switched on (chrome://gpu shows why not).': 'Ce navigateur ne donne à la page aucune carte graphique (WebGPU) : les modèles tournent sur le processeur. WebGPU nécessite https ou localhost, et un navigateur qui l’a activé (chrome://gpu indique pourquoi ce n’est pas le cas).',
  'Timing…': 'Mesure…',
  'Time the handwriting reader': 'Mesurer le lecteur d’écriture manuscrite',
  'Size of the model': 'Taille du modèle',
  'Exact ({mb} MB)': 'Exacte ({mb} Mo)',
  'Compact ({mb} MB)': 'Compacte ({mb} Mo)',
  'Compact is a third smaller and reads about two points less exactly. In a browser it is the one the graphics card can run (WebGPU), and much faster there. Changing it downloads the other file.': 'La version compacte est un tiers plus petite et lit environ deux points moins exactement. Dans un navigateur, c’est celle que la carte graphique peut faire tourner (WebGPU), et bien plus vite. La changer télécharge l’autre fichier.',
  'Run models on': 'Faire tourner les modèles sur',
  'Looking for an accelerator…': 'Recherche d’un accélérateur…',
  'Available on this device: {names}': 'Disponible sur cet appareil : {names}',
  'This device has no accelerator the app can use: models always run on the processor.': 'Cet appareil n’a aucun accélérateur utilisable par l’application : les modèles tournent toujours sur le processeur.',
  'Accelerator when available': 'Accélérateur si disponible',
  'Processor only': 'Processeur seulement',
  'Graphics card ({mb} MB)': 'Carte graphique ({mb} Mo)',
  'Small ({mb} MB)': 'Petit ({mb} Mo)',
  'Full ({mb} MB)': 'Complet ({mb} Mo)',
  'Check the accelerator with a small test model': 'Vérifier l’accélérateur avec un petit modèle d’essai',
  'Checking…': 'Vérification…',
  'Not available in the browser.': 'Non disponible dans le navigateur.',
  'Opened on': 'Ouvert sur',
  'Failed': 'Échec',
  'differs from the processor by at most {n}': 'diffère du processeur d’au plus {n}',
  'preparing the model for {name} (can take minutes)': 'préparation du modèle pour {name} (peut prendre plusieurs minutes)',
  'preparing the model': 'préparation du modèle',
  'Graphics card is the encoder in 16 bits, for a graphics card runtime (AMD\'s cannot run the 8-bit one): twice the size, much quicker there, reads about as well. Changing it downloads the encoder. Full is the published encoder unchanged, in 32 bits: the largest, reads like the original, and the form a phone\'s accelerator can take most of.': 'La carte graphique est l’encodeur en 16 bits, pour un environnement de carte graphique (celui d’AMD ne peut pas exécuter la version 8 bits) : deux fois plus gros, bien plus rapide là-bas, lit à peu près aussi bien. La changer télécharge l’encodeur. Complet est l’encodeur publié tel quel, en 32 bits : le plus gros, il lit comme l’original, et c’est la forme que peut prendre le plus souvent un accélérateur de téléphone.',
  'Graphics card is for a graphics card runtime (AMD\'s cannot run the quantised ones): not shrunk, reads like Exact.': 'La carte graphique est destinée à un environnement de carte graphique (celui d’AMD ne peut pas exécuter les versions quantifiées) : non réduite, elle lit comme Exacte.',
  'Preparing…': 'Préparation…',
  'Plans can only be made for the "Graphics card" size of the handwriting or the formula model (see their settings), once it is installed.': 'Des plans ne peuvent être faits que pour la taille « Carte graphique » du modèle d’écriture ou de formules (voir leurs réglages), une fois installé.',
  'Plan for the graphics card': 'Plan pour la carte graphique',
  'Precompile the formula plan': 'Précompiler le plan des formules',
  'Done: the plan is made and kept.': 'Terminé : le plan est fait et gardé.',
  'Formula pictures are always the same size, so there is nothing to pad and one plan to make. The graphics card works it out once (about 2 minutes) and keeps it; until then the first formula can wait.': 'Les images de formules ont toujours la même taille : il n’y a donc rien à compléter et un seul plan à faire. La carte graphique le calcule une fois (environ 2 minutes) et le garde ; en attendant, la première formule peut attendre.',
  'Precompile picture sizes': 'Précompiler les tailles d’images',
  'Handwriting: all {all} picture sizes of this quality have their plan.': 'Écriture : les {all} tailles d’image de cette qualité ont leur plan.',
  'Formulas: the plan is made.': 'Formules : le plan est fait.',
  'Formulas: no plan yet.': 'Formules : pas encore de plan.',
  'Waiting for the block that is being read in the background...': 'En attente du bloc en cours de lecture en arrière-plan...',
  'handwriting': 'écriture manuscrite',
  'formulas': 'formules',
  'speech': 'parole',
  'search': 'recherche',
  'embedding model': 'modèle d’embeddings',
  'language model': 'modèle de langue',
  'picture part': 'partie image',
  'text part': 'partie texte',
  'sound part': 'partie son',
  '{model} ({purpose}): {file}': '{model} ({purpose}) : {file}',
  '{model} ({purpose}), {part}: {file}': '{model} ({purpose}), {part} : {file}',
  'processor (CPU)': 'processeur (CPU)',
  'processor (in the browser)': 'processeur (dans le navigateur)',
  'graphics card ({name})': 'carte graphique ({name})',
  'accelerator ({name})': 'accélérateur ({name})',
  'processor ({name})': 'processeur ({name})',
  'graphics card making a plan': 'carte graphique en train de faire un plan',
  'graphics card': 'carte graphique',
  'accelerator': 'accélérateur',
  'processor': 'processeur',
  'Size {done} of {total} done. Each takes 4 to 5 minutes; the app can be used meanwhile, and what is done is kept.': 'Taille {done} sur {total} faite. Chacune prend 4 à 5 minutes ; l’application reste utilisable entre-temps, et ce qui est fait est gardé.',
  'Makes the graphics card\'s plan for every picture size of the handwriting reader now, for the quality chosen (about an hour the first time, once; another quality needs its own), so that no reading has to wait for one. Needs the "Graphics card" size of the handwriting model.': 'Fait dès maintenant le plan de la carte graphique pour chaque taille d’image du lecteur d’écriture, pour la qualité choisie (environ une heure la première fois, une seule fois ; une autre qualité a besoin du sien), pour qu’aucune lecture n’attende. Nécessite la taille « Carte graphique » du modèle d’écriture.',
  'Pad to fixed sizes': 'Compléter aux tailles fixes',
  'Applies to models opened from now on; restart the app to switch all of them. Models that write text word by word always use the processor.': 'S’applique aux modèles ouverts à partir de maintenant ; redémarrez l’application pour les changer tous. Les modèles qui écrivent le texte mot à mot utilisent toujours le processeur.',
  'Graphics card runtime': 'Environnement de carte graphique',
  'Running now: {name} (ONNX Runtime {version})': 'En cours d’utilisation : {name} (ONNX Runtime {version})',
  'the one in the app (processor only)': 'celui de l’application (processeur seulement)',
  'The one in the app (processor only)': 'Celui de l’application (processeur seulement)',
  'The chosen runtime could not be opened: {why}': 'L’environnement choisi n’a pas pu être ouvert : {why}',
  'No runtime with graphics card support found. Put one in this folder (see docs/gpu-runtime-packs.md): {folder}': 'Aucun environnement avec prise en charge de carte graphique trouvé. Placez-en un dans ce dossier (voir docs/gpu-runtime-packs.md) : {folder}',
  'Takes effect when the app is started again. Folder of the runtimes: {folder}': 'Prend effet au prochain démarrage de l’application. Dossier des environnements : {folder}',
  'High refresh rate': 'Taux de rafraîchissement élevé',
  'Asks the screen for the fastest refresh rate it has (90 or 120 Hz on some devices): scrolling and drawing look smoother, and the battery lasts less. Android may still slow it down, for example in battery saver.': 'Demande à l’écran son taux de rafraîchissement le plus rapide (90 ou 120 Hz sur certains appareils) : le défilement et le dessin sont plus fluides, et la batterie dure moins. Android peut quand même le ralentir, par exemple en économie d’énergie.',
  'Turn it off when the battery is below': 'Le désactiver quand la batterie est en dessous de',
  'Never': 'Jamais',
  '{n} %': '{n} %',
  'Truth table': 'Table de vérité',
  'Type a formula: p -> q, !p | q, (p and q) or not r, or in LaTeX. Put = between two formulas to see whether they are the same.': 'Saisissez une formule : p -> q, !p | q, (p et q) ou non r, ou en LaTeX. Mettez = entre deux formules pour voir si elles sont identiques.',
  'I cannot read that as a formula. Use single letters for the statements.': 'Je ne peux pas lire cela comme une formule. Utilisez des lettres seules pour les énoncés.',
  'That has too many letters (at most 10).': 'Il y a trop de lettres (10 au maximum).',
  '0 first': '0 d’abord',
  '1 first': '1 d’abord',
  'Copy as Markdown': 'Copier en Markdown',
  'Copy as LaTeX': 'Copier en LaTeX',
  'Put on the page': 'Mettre sur la page',
  'Copied': 'Copié',
  'Always true (a tautology)': 'Toujours vraie (une tautologie)',
  'Never true (a contradiction)': 'Jamais vraie (une contradiction)',
  'Sometimes true': 'Parfois vraie',
  'The same in every row': 'La même dans chaque ligne',
  'Not the same: they differ in {n} of {total} rows': 'Pas identiques : elles diffèrent sur {n} lignes sur {total}',
  'The second follows from the first': 'La seconde découle de la première',
  'The second does not follow from the first': 'La seconde ne découle pas de la première',
  'Other forms of the formula': 'Autres formes de la formule',
  'Of the first formula': 'De la première formule',
  'True in rows': 'Vraie dans les lignes',
  'False in rows': 'Fausse dans les lignes',
  'Shortest sum of products': 'Somme de produits la plus courte',
  'Shortest product of sums': 'Produit de sommes le plus court',
  'Every true row as a product': 'Chaque ligne vraie comme un produit',
  'Every false row as a sum': 'Chaque ligne fausse comme une somme',
  'none': 'aucune',
  'none (it is never true)': 'aucune (elle n’est jamais vraie)',
  'none (it is always true)': 'aucune (elle est toujours vraie)',
  'Make the truth table of a formula': 'Faire la table de vérité d’une formule',
  'Outline or flowchart': 'Schéma ou organigramme',
  'Automaton': 'Automate',
  'Tree': 'Arbre',
  'Show an example': 'Montrer un exemple',
  'One line for each arrow: q0 -a-> q1 (q0 --a,b--> q1 for two symbols, -eps-> for the empty word). Say where it starts and which states accept: start: q0, accept: q2 (or >q0 and *q2).': 'Une ligne par flèche : q0 -a-> q1 (q0 --a,b--> q1 pour deux symboles, -eps-> pour le mot vide). Indiquez où il commence et quels états acceptent : start: q0, accept: q2 (ou >q0 et *q2).',
  'Brackets: A(B(D,E),C), a gap for a missing child: 8(3,10(,14). Or numbers put into a search tree, bst: 8 3 10 1 (also avl:, minheap:, maxheap:, array: 1 3 2 4). Lines after that: insert 7, delete 3.': 'Parenthèses : A(B(D,E),C), un trou pour un enfant manquant : 8(3,10(,14). Ou des nombres insérés dans un arbre de recherche, bst: 8 3 10 1 (aussi avl:, minheap:, maxheap:, array: 1 3 2 4). Lignes suivantes : insert 7, delete 3.',
  'One line for each edge: A - B, an arrow A -> B, a weight A -3- B (or A - B : 3), a chain A - B - C. A node on its own gets a line of its own. start: A says where the searches begin.': 'Une ligne par arête : A - B, une flèche A -> B, un poids A -3- B (ou A - B : 3), une chaîne A - B - C. Un nœud seul a sa propre ligne. start: A indique où commencent les parcours.',
  'Show the balance factors': 'Montrer les facteurs d’équilibre',
  'Line {n} is not understood: {text}': 'La ligne {n} n’est pas comprise : {text}',
  'Try a word': 'Essayer un mot',
  'accepted': 'accepté',
  'rejected': 'refusé',
  'stuck after {n} symbols': 'bloqué après {n} symboles',
  'Make it deterministic': 'Le rendre déterministe',
  'Make it smallest': 'Le rendre le plus petit',
