  'NFA with ε moves': 'AFN avec transitions ε',
  'no (a missing arrow is a dead end)': 'non (une flèche manquante est une impasse)',
  'none (there is a cycle)': 'aucun (il y a un cycle)',
  'not for negative weights': 'pas pour des poids négatifs',
  'no start state (write start: q0 or >q0)': 'pas d’état initial (écrivez start: q0 ou >q0)',
  'no accepting state (write accept: q1 or *q1)': 'pas d’état acceptant (écrivez accept: q1 ou *q1)',
  'a bracket is not closed': 'une parenthèse n’est pas fermée',
  'a node has no name before "("': 'un nœud n’a pas de nom avant « ( »',
  'the first place is the root, it cannot be a hole': 'la première place est la racine, elle ne peut pas être un trou',
  'Connect temporarily': 'Se connecter temporairement',
  'Fetching the note from your other device...': 'Récupération de la note depuis votre autre appareil...',
  'The note could not be fetched. Is the device that has it online?': 'La note n’a pas pu être récupérée. L’appareil qui la possède est-il en ligne ?',
  'Scan the code of the web version': 'Scanner le code de la version web',
  'On a computer that is not yours: "Connect temporarily" shows a code that you scan with your phone. Your notes are listed here, and each one comes when you open it. This browser forgets them again when the tab is closed.': 'Sur un ordinateur qui n’est pas le vôtre : « Se connecter temporairement » affiche un code que vous scannez avec votre téléphone. Vos notes sont listées ici, et chacune arrive quand vous l’ouvrez. Ce navigateur les oublie à nouveau quand l’onglet est fermé.',
  'This browser is connected temporarily. There are changes that no other device has yet: they are lost if you close the tab before the next sync.': 'Ce navigateur est connecté temporairement. Il y a des modifications qu’aucun autre appareil n’a encore : elles seront perdues si vous fermez l’onglet avant la prochaine synchronisation.',
  'This browser is connected temporarily. Everything here is on your other devices; it is forgotten when you sign out or close the tab.': 'Ce navigateur est connecté temporairement. Tout ce qui est ici se trouve sur vos autres appareils ; tout est oublié quand vous vous déconnectez ou fermez l’onglet.',
  'Sign out and forget everything here': 'Se déconnecter et tout oublier ici',
  'Sign out of this browser?': 'Se déconnecter de ce navigateur ?',
  'This browser forgets the notes and the profile. No other device is connected, so notes that are only here are lost.': 'Ce navigateur oublie les notes et le profil. Aucun autre appareil n’est connecté, donc les notes qui ne sont que ici seront perdues.',
  'There are changes here that no other device has yet. They are lost when you sign out. Press "Sync now" first and wait until it is done to keep them. This browser forgets the notes and the profile either way.': 'Il y a ici des modifications qu’aucun autre appareil n’a encore. Elles sont perdues à la déconnexion. Appuyez d’abord sur « Synchroniser maintenant » et attendez la fin pour les garder. Ce navigateur oublie de toute façon les notes et le profil.',
  'This browser forgets the notes and the profile. Your other devices keep everything.': 'Ce navigateur oublie les notes et le profil. Vos autres appareils gardent tout.',
  'Scan this code with your phone: with the camera, or in Notation under Settings → Sync profile → "Scan the code of the web version".': 'Scannez ce code avec votre téléphone : avec la caméra, ou dans Notation sous Réglages → Profil de synchronisation → « Scanner le code de la version web ».',
  'Waiting for your phone...': 'En attente de votre téléphone...',
  'This browser is signed in until you sign out or close the tab, and then forgets your notes. The code works for ten minutes and only once; your phone still asks you before it lets this browser in.': 'Ce navigateur reste connecté jusqu’à votre déconnexion ou la fermeture de l’onglet, puis oublie vos notes. Le code fonctionne dix minutes et une seule fois ; votre téléphone vous demande toujours avant de laisser entrer ce navigateur.',
  'Point the camera at the code that the web version shows.': 'Pointez la caméra vers le code affiché par la version web.',
  'temporary': 'temporaire',
  'Sign in with your cloud folder': 'Se connecter avec votre dossier cloud',
  'signed in with the recovery key': 'connecté avec la clé de récupération',
  'Your recovery key': 'Votre clé de récupération',
  'Keep it in a password manager or write it on paper. It is shown only now and the app does not keep it. With this key and your cloud account you can sign in to your profile on a new device; without it, only a link from one of your devices works.': 'Conservez-la dans un gestionnaire de mots de passe ou notez-la sur papier. Elle n’est affichée que maintenant et l’application ne la garde pas. Avec cette clé et votre compte cloud, vous pouvez vous connecter à votre profil sur un nouvel appareil ; sans elle, seul un lien depuis l’un de vos appareils fonctionne.',
  'I have saved the key': 'J’ai enregistré la clé',
  'Use the folder your other devices sync through, and the recovery key that was shown when signing in was turned on there. Your notes, folders and settings come to this device.': 'Utilisez le dossier par lequel vos autres appareils se synchronisent, et la clé de récupération affichée à la connexion a été activée là-bas. Vos notes, dossiers et réglages arrivent sur cet appareil.',
  '{service} is connected.': '{service} est connecté.',
  'Connect your account first:': 'Connectez d’abord votre compte :',
  'In a browser, your Nextcloud has to allow this website to talk to it (CORS headers); the documentation says which.': 'Dans un navigateur, votre Nextcloud doit autoriser ce site à lui parler (en-têtes CORS) ; la documentation indique lesquels.',
  'Recovery key': 'Clé de récupération',
  '"Sign out" in the menu removes everything from this browser again.': '« Se déconnecter » dans le menu retire à nouveau tout de ce navigateur.',
  'Sign in': 'Se connecter',
  'Sign in with this folder?': 'Se connecter avec ce dossier ?',
  'Anyone who has the recovery key and can open this cloud folder will be able to sign in to your profile and read your notes, without anyone saying yes on one of your other devices. Your devices show each device that signs in this way, and you can take it out. The key is shown once and not kept by the app. Adding a device with a link works as before.': 'Quiconque possède la clé de récupération et peut ouvrir ce dossier cloud pourra se connecter à votre profil et lire vos notes, sans que personne dise oui sur l’un de vos autres appareils. Vos appareils affichent chaque appareil qui se connecte ainsi, et vous pouvez le retirer. La clé n’est affichée qu’une fois et l’application ne la garde pas. Ajouter un appareil avec un lien fonctionne comme avant.',
  'Turn on': 'Activer',
  'Turn off signing in with the folder?': 'Désactiver la connexion avec le dossier ?',
  'The sign-in file is taken out of the folder, so the recovery key stops working. Devices that are already in stay in.': 'Le fichier de connexion est retiré du dossier, donc la clé de récupération cesse de fonctionner. Les appareils déjà présents restent.',
  'Turn off': 'Désactiver',
  'Make a new recovery key?': 'Créer une nouvelle clé de récupération ?',
  'The old key stops working at once. Devices that signed in with it stay in; to cut one off, take it out of the list of devices.': 'L’ancienne clé cesse de fonctionner immédiatement. Les appareils qui se sont connectés avec elle restent ; pour en couper un, retirez-le de la liste des appareils.',
  'Make a new key': 'Créer une nouvelle clé',
  'Let me sign in with this folder': 'Me laisser me connecter avec ce dossier',
  'On a new device or in a browser, sign in with this cloud account and a recovery key instead of a link and a yes on another device. Off by default: adding a device with a link stays the careful way.': 'Sur un nouvel appareil ou dans un navigateur, connectez-vous avec ce compte cloud et une clé de récupération au lieu d’un lien et d’un oui sur un autre appareil. Désactivé par défaut : ajouter un appareil avec un lien reste la méthode prudente.',
  'Needs the sync through the folder to be on, with the account connected on this device.': 'Nécessite que la synchronisation par dossier soit activée, avec le compte connecté sur cet appareil.',
  'Make a new recovery key': 'Créer une nouvelle clé de récupération',
  'Signed in with the recovery key: {devices}': 'Connecté avec la clé de récupération : {devices}',
  'This device is part of a profile already. Leave it first to sign in to another.': 'Cet appareil fait déjà partie d’un profil. Quittez-le d’abord pour vous connecter à un autre.',
  'Connect the account of {service} first.': 'Connectez d’abord le compte de {service}.',
  'That recovery key does not open this folder. Check it for typing mistakes, and that it is the latest one if you made a new key.': 'Cette clé de récupération n’ouvre pas ce dossier. Vérifiez les fautes de frappe, et qu’il s’agit de la dernière si vous avez créé une nouvelle clé.',
  'The sign-in file in the folder cannot be read.': 'Le fichier de connexion du dossier est illisible.',
  'The sign-in file in the folder is from a newer version of the app: update the app.': 'Le fichier de connexion du dossier vient d’une version plus récente de l’application : mettez l’application à jour.',
  'Signing in needs the sync through a cloud folder to be on, with the account connected on this device.': 'La connexion nécessite que la synchronisation par dossier cloud soit activée, avec le compte connecté sur cet appareil.',
  'Signing in is not on.': 'La connexion n’est pas activée.',
  'That is not a recovery key. It has 25 letters and digits, like ABCDE-FGHJK-MNPQR-STUVW-XY234.': 'Ce n’est pas une clé de récupération. Elle comporte 25 lettres et chiffres, comme ABCDE-FGHJK-MNPQR-STUVW-XY234.',
  'Nothing to sign in to was found in this folder. Is signing in turned on on your other device, and is the folder name the same?': 'Rien à quoi se connecter n’a été trouvé dans ce dossier. La connexion est-elle activée sur votre autre appareil, et le nom du dossier est-il le même ?',
  'Enter the address of your Nextcloud first.': 'Saisissez d’abord l’adresse de votre Nextcloud.',
  'Waiting for you to approve in the browser...': 'En attente de votre approbation dans le navigateur...',
  'Log in with the browser': 'Se connecter avec le navigateur',
  'The browser could not be opened. Open this address yourself:': 'Le navigateur n’a pas pu être ouvert. Ouvrez vous-même cette adresse :',
  'Or enter an app password yourself:': 'Ou saisissez vous-même un mot de passe d’application :',
  'That is not a server address.': 'Ce n’est pas une adresse de serveur.',
  'This server did not start a login. Is it a Nextcloud (version 16 or newer), and is the address right?': 'Ce serveur n’a pas lancé de connexion. Est-ce un Nextcloud (version 16 ou plus récente), et l’adresse est-elle bonne ?',
  'The server did not hand over a login.': 'Le serveur n’a pas fourni de connexion.',
  'The login was not approved in time. Try again.': 'La connexion n’a pas été approuvée à temps. Réessayez.',
  'The server could not be reached: {error}': 'Impossible de joindre le serveur : {error}',
  'The password of the Nextcloud account is not in the keystore of this device. Log in again in the settings under Sync and sharing.': 'Le mot de passe du compte Nextcloud n’est pas dans le trousseau de cet appareil. Reconnectez-vous dans les réglages, sous Synchronisation et partage.',
  'The password of this account is not in the keystore of this device. Log in again.': 'Le mot de passe de ce compte n’est pas dans le trousseau de cet appareil. Reconnectez-vous.',
  'Choose calendars': 'Choisir les agendas',
  'The system keystore did not keep the password, so the account was not saved. Is the keyring unlocked?': 'Le trousseau du système n’a pas conservé le mot de passe, donc le compte n’a pas été enregistré. Le trousseau est-il déverrouillé ?',
  'Eyedropper': 'Pipette',
  'Pick a color from anything on the page (a drawing, a picture, a PDF) for the pen: tap the button or press I, then touch the color.': 'Prenez une couleur sur n’importe quoi de la page (un dessin, une image, un PDF) pour le stylo : touchez le bouton ou appuyez sur I, puis touchez la couleur.',
  'Eyedropper: touch anything on the page to draw in its color (I)': 'Pipette : touchez n’importe quoi sur la page pour dessiner dans sa couleur (I)',
  'Free transform': 'Transformation libre',
  'Bend selected drawings: distort them by the corners, give them perspective, skew them, turn them by any angle or warp them with a net. The whole change is one step to take back.': 'Déformer les dessins sélectionnés : les étirer par les coins, leur donner une perspective, les cisailler, les tourner d’un angle quelconque ou les déformer avec une grille. Toute la modification est une seule étape à annuler.',
  'Transform: distort, perspective, skew, rotate, warp': 'Transformer : déformer, perspective, cisailler, tourner, plier',
  'Distort: pull the corners anywhere': 'Déformer : tirer les coins n’importe où',
  'Perspective: pull a corner, the next one follows': 'Perspective : tirer un coin, le suivant suit',
  'Skew: slide the edges': 'Cisaillement : faire glisser les bords',
  'Rotate (Shift: in steps of 15°)': 'Tourner (Maj : par pas de 15°)',
  'Warp: bend the drawing with a net': 'Plier : courber le dessin avec une grille',
  'Start again': 'Recommencer',
  'Fill bucket': 'Pot de peinture',
  'Fill a closed area of a drawing with the pen color by touching it: the area is found from the lines round it, and small gaps in them can be closed. The fill is a shape under the lines, so it can be recolored or moved later.': 'Remplir une zone fermée d’un dessin avec la couleur du stylo en la touchant : la zone est trouvée d’après les lignes qui l’entourent, et les petits trous dans ces lignes peuvent être fermés. Le remplissage est une forme sous les lignes, on peut donc le recolorer ou le déplacer plus tard.',
  'Fill bucket: touch a closed area to fill it with the pen color (G)': 'Pot de peinture : touchez une zone fermée pour la remplir avec la couleur du stylo (G)',
  'Gap closing: how big a gap in the lines still closes an area': 'Fermeture des trous : la taille d’un trou dans les lignes qui ferme encore une zone',
  'No gap closing': 'Sans fermeture des trous',
  'Small gaps': 'Petits trous',
  'Medium gaps': 'Trous moyens',
  'Large gaps': 'Grands trous',
  'There are no lines to close an area yet: draw the outline first.': 'Il n’y a pas encore de lignes pour fermer une zone : tracez d’abord le contour.',
  'That area is not closed. Close the lines, or turn gap closing up (the button beside the bucket).': 'Cette zone n’est pas fermée. Fermez les lignes, ou augmentez la fermeture des trous (le bouton à côté du pot de peinture).',
  'That is on a line: touch the area beside it.': 'C’est sur une ligne : touchez la zone à côté.',
  'Turn the canvas left': 'Tourner la toile à gauche',
  'Turn the canvas right': 'Tourner la toile à droite',
  'Put the canvas straight': 'Remettre la toile droite',
  'The canvas is turned: tap to put it straight': 'La toile est tournée : touchez pour la remettre droite',
  'Bring your notes from another app': 'Apporter vos notes d’une autre application',
  'Obsidian: a vault folder': 'Obsidian : un dossier de coffre',
  'Notes, folders, pictures, PDFs and tags are taken; links between notes keep working.': 'Notes, dossiers, images, PDF et étiquettes sont repris ; les liens entre les notes continuent de fonctionner.',
  'Obsidian: a vault as a zip': 'Obsidian : un coffre en zip',
  'The same, from a zip of the vault folder.': 'La même chose, à partir d’un zip du dossier du coffre.',
  'Notion: an export': 'Notion : un export',
  'In Notion: Settings, Export all workspace content, Markdown & CSV. Pick the zip you get.': 'Dans Notion : Paramètres, Exporter tout le contenu de l’espace de travail, Markdown et CSV. Choisissez le zip obtenu.',
  'GoodNotes: PDFs or a .goodnotes file': 'GoodNotes : des PDF ou un fichier .goodnotes',
  'In GoodNotes: Share, Export as PDF. Handwriting stays as it looks. A .goodnotes file can only give its PDFs.': 'Dans GoodNotes : Partager, Exporter en PDF. L’écriture manuscrite reste telle qu’elle apparaît. Un fichier .goodnotes ne peut fournir que ses PDF.',
  'Reading your notes...': 'Lecture de vos notes...',
  'Pick the vault folder': 'Choisissez le dossier du coffre',
  'Pick the Notion export (zip)': 'Choisissez l’export Notion (zip)',
  'Pick the vault (zip)': 'Choisissez le coffre (zip)',
  'Pick the PDFs or the .goodnotes files': 'Choisissez les PDF ou les fichiers .goodnotes',
  'What is written by hand in "{name}" is in a format that cannot be read. Only its PDF pages were taken; to keep the handwriting, export the notebook as a PDF in GoodNotes.': 'L’écriture manuscrite de « {name} » est dans un format illisible. Seules ses pages PDF ont été reprises ; pour garder l’écriture, exportez le carnet en PDF depuis GoodNotes.',
  'Could not read the notes: {error}': 'Impossible de lire les notes : {error}',
  'Nothing was taken in': 'Rien n’a été repris',
  'Your notes are here': 'Vos notes sont ici',
  '{n} PDF': '{n} PDF',
  '{n} PDFs': '{n} PDF',
