  'Open a note': 'Ouvrir une note',
  'This is not a zip file.': 'Ce n’est pas un fichier zip.',
  'This is not a GoodNotes file. In GoodNotes, choose Share → Export as PDF and open that PDF here.': 'Ce n’est pas un fichier GoodNotes. Dans GoodNotes, choisissez Partager → Exporter en PDF, et ouvrez ce PDF ici.',
  'There is no PDF in this GoodNotes file, and what is written in it cannot be read. In GoodNotes, choose Share → Export as PDF and open that PDF here.': 'Il n’y a aucun PDF dans ce fichier GoodNotes, et ce qui y est écrit ne peut pas être lu. Dans GoodNotes, choisissez Partager → Exporter en PDF, et ouvrez ce PDF ici.',
