  'You press a trigger (a shortcut or the pen button)': 'Vous appuyez sur un déclencheur (un raccourci ou le bouton du stylo)',
  'how many pages the note has now': 'le nombre de pages que la note a maintenant',
  'how many highlights were added': 'le nombre de surlignages ajoutés',
  'the title of the note it links to': 'le titre de la note liée',
  'the file name of the PDF': 'le nom du fichier du PDF',
  'the title of the recording': 'le titre de l’enregistrement',
  'how long it is, in minutes': 'sa durée, en minutes',
  'the day the task was due': 'le jour où la tâche était due',
  'the number of the trigger': 'le numéro du déclencheur',
  'note, clip, page, pdf or picture': 'note, extrait, page, pdf ou image',
  'the address it came from': 'l’adresse d’où elle vient',
