  'Folder for a new daily note': 'Dossier pour une nouvelle note du jour',
  'Text to add': 'Texte à ajouter',
  'It goes in a box under the rest of the last page': 'Il va dans une case sous le reste de la dernière page',
  'Tag': 'Étiquette',
  'A tag of the tag tree, e.g. school/maths; the words in braces of the event can be used: reading/{kind}': 'Une étiquette de l’arborescence, p. ex. ecole/maths ; les mots entre accolades de l’événement peuvent être utilisés : lecture/{kind}',
  'Title of the note': 'Titre de la note',
  '{title} is the title of the event; {date} today': '{title} est le titre de l’événement ; {date} la date du jour',
  'Template (optional)': 'Modèle (facultatif)',
  '{title} is the name of the event, {day} its day, {start} its time': '{title} est le nom de l’événement, {day} son jour, {start} son heure',
  'Bring along what is still open from the last meeting': 'Reprendre ce qui est resté ouvert à la dernière réunion',
  'Yes: the to-do lines of the last note of that name': 'Oui : les lignes à faire de la dernière note de ce nom',
  'This evening (18:00)': 'Ce soir (18 h)',
  'Tomorrow morning (9:00)': 'Demain matin (9 h)',
  'In a week (9:00)': 'Dans une semaine (9 h)',
  'Save the pictures in this folder': 'Enregistrer les images dans ce dossier',
  'the note\'s': 'de la note',
  '{title} is empty, {date} today\'s date': '{title} est vide, {date} la date du jour',
  '{title} is the event\'s title, {date} today\'s date': '{title} est le titre de l’événement, {date} la date du jour',
  '{summary} is what is to be done, {line} the whole line, {title} the note\'s title. The task is on the day the line says ("by Friday"), else on the day below': '{summary} est ce qui est à faire, {line} la ligne entière, {title} le titre de la note. La tâche est au jour indiqué par la ligne (« avant vendredi »), sinon au jour ci-dessous',
  'The page the note was made from (its address, its title, the site and the day it was kept) is added to the sources of the citations, to cite in any note with [@key]. A page that is a source already is not added again.': 'La page d’où vient la note (son adresse, son titre, le site et le jour où elle a été gardée) est ajoutée aux sources des citations, pour être citée dans n’importe quelle note avec [@clé]. Une page qui est déjà une source n’est pas ajoutée une seconde fois.',
  'The note is listed on the dashboard: "Still relevant?" with the answers: keep it, archive it, remind me in a week, make flashcards of it, or not now. Nothing changes until you answer.': 'La note apparaît sur le tableau de bord : « Toujours pertinent ? » avec les réponses : la garder, l’archiver, me le rappeler dans une semaine, en faire des cartes mémoire, ou pas maintenant. Rien ne change tant que vous n’avez pas répondu.',
  'The note is starred, so that it is listed as a favourite on the dashboard.': 'La note reçoit une étoile, pour être listée comme favorite sur le tableau de bord.',
  'The assistant reads the text of the note and writes its outline (topics and points) into a text box under the rest of the last page. A later run replaces it. Needs the assistant.': 'L’assistant lit le texte de la note et écrit son plan (thèmes et points) dans une zone de texte sous le reste de la dernière page. Une exécution ultérieure le remplace. Nécessite l’assistant.',
  'The assistant reads the text of the note and writes a short summary into a text box under the rest of the last page. A later run replaces it. Needs the assistant.': 'L’assistant lit le texte de la note et écrit un bref résumé dans une zone de texte sous le reste de la dernière page. Une exécution ultérieure le remplace. Nécessite l’assistant.',
