  'Often': 'Souvent',
  'When the model is unsure of a formula, it reads it again with a thinner and a thicker pen and keeps the surest reading. Normal does this for about one formula in ten and reads about 2 points more right; Often is about three in ten; Never is the quickest.': 'Quand le modèle hésite sur une formule, il la relit avec un stylo plus fin et un plus épais, et garde la lecture la plus sûre. Normal fait cela pour environ une formule sur dix et lit environ 2 points de plus juste ; Souvent, environ trois sur dix ; Jamais est le plus rapide.',
