  'Copy formatting, then select text and press again to apply it': 'Copier la mise en forme, puis sélectionner le texte et appuyer de nouveau pour l’appliquer',
  'A title, an introduction, the main part and a conclusion, the sources at the end': 'Un titre, une introduction, la partie principale et une conclusion, les sources à la fin',
  'Every paragraph of a kind takes its look; what is picked for single words stays.': 'Chaque paragraphe d’un type prend son aspect ; ce qui est choisi pour des mots isolés reste.',
  'Read from your drawing: {nodes} circles, {edges} lines. Check the names, then put it on the page; your drawing is replaced.': 'Lu depuis votre dessin : {nodes} cercles, {edges} lignes. Vérifiez les noms, puis placez-le sur la page ; votre dessin est remplacé.',
  'This package was exported in the newest Anki format. Export it again with "Support older Anki versions" ticked.': 'Ce paquet a été exporté dans le format Anki le plus récent. Exportez-le de nouveau en cochant « Prendre en charge les anciennes versions d’Anki ».',
  '{page} is the number of the page, {pages} how many there are, {title} the title of the note, {date} today.': '{page} est le numéro de la page, {pages} leur nombre, {title} le titre de la note, {date} la date du jour.',
  'Remove this PDF?': 'Retirer ce PDF ?',
  '"{name}" and its pages are taken out of the note, with what is drawn or written on them.': '« {name} » et ses pages sont retirés de la note, avec ce qui est dessiné ou écrit dessus.',
  'The PDFs of this note': 'Les PDF de cette note',
  '{n} pages': '{n} pages',
  'Remove {name}…': 'Retirer {name}…',
  '{n} PDFs ({pages} Pages)': '{n} PDF ({pages} pages)',
  'The pages of the PDFs in the file do not fit them; the note is opened without them': 'Les pages des PDF du fichier ne leur correspondent pas ; la note est ouverte sans elles',
  'A PDF in the file does not match its checksum and was left out': 'Un PDF du fichier ne correspond pas à sa somme de contrôle et a été omis',
  'You are on mobile data. These models are large: untick them to download later on Wi-Fi (the settings have the same list), or go ahead if your plan allows it.': 'Vous êtes en données mobiles. Ces modèles sont volumineux : décochez-les pour les télécharger plus tard en Wi-Fi (les réglages ont la même liste), ou poursuivez si votre forfait le permet.',
  'Export the whole note as Markdown': 'Exporter toute la note en Markdown',
  'Export as Markdown': 'Exporter en Markdown',
  'Handwriting is in it as read by the app: check it. Drawings are not in it.': 'L’écriture manuscrite y figure telle que lue par l’application : vérifiez-la. Les dessins n’y figurent pas.',
  'Syncs by itself whenever two of your devices are online at the same time. This needs the signalling server: the device stays connected to it, which tells it that a device of yours is online (it cannot tell which, or what is in your notes). Off: only when you press "Sync now".': 'Se synchronise tout seul dès que deux de vos appareils sont en ligne en même temps. Cela nécessite le serveur de signalisation : l’appareil reste connecté à lui, ce qui lui indique qu’un de vos appareils est en ligne (il ne peut pas savoir lequel, ni ce qu’il y a dans vos notes). Désactivé : seulement quand vous appuyez sur « Synchroniser maintenant ».',
  'For devices that are not online at the same time: each puts what changed in a folder on your cloud storage and takes in what the others put there, without the signalling server. Two things still need it: handing the cloud accounts to your other devices (when two of them sync directly; or connect the account on each device yourself), and working on one note on two devices at the same time.': 'Pour les appareils qui ne sont pas en ligne en même temps : chacun dépose ce qui a changé dans un dossier de votre stockage cloud et reprend ce que les autres y ont déposé, sans le serveur de signalisation. Deux choses en ont encore besoin : remettre les comptes cloud à vos autres appareils (quand deux d’entre eux se synchronisent directement ; ou connecter le compte sur chaque appareil vous-même), et travailler sur une même note depuis deux appareils en même temps.',
  'A file in the folder is not sealed with the key of this profile; it was not taken.': 'Un fichier du dossier n’est pas scellé avec la clé de ce profil ; il n’a pas été pris.',
  'Your notes are also kept in sync through the cloud folder below, also when your devices are not online at the same time.': 'Vos notes sont aussi synchronisées par le dossier cloud ci-dessous, même quand vos appareils ne sont pas en ligne en même temps.',
  'While a note is open, this device is connected to the signalling server and tells your other devices which notes are open; a note that is open on two of them is edited together live. What it tells them is encrypted: the server cannot see which note it is, nor that the same note is opened again. Off: the server hears nothing from this device while a note is open, and a note changed on two devices is brought together at the next sync.': 'Pendant qu’une note est ouverte, cet appareil est connecté au serveur de signalisation et lui indique quelles notes sont ouvertes ; une note ouverte sur deux de vos appareils est modifiée ensemble en direct. Ce qu’il leur transmet est chiffré : le serveur ne peut ni voir de quelle note il s’agit, ni que la même note est ouverte à nouveau. Désactivé : le serveur n’entend rien de cet appareil pendant qu’une note est ouverte, et une note modifiée sur deux appareils est réunie à la synchronisation suivante.',
  'Handwriting: {done} of {all} picture sizes of this quality have their plan. Missing: {missing} (widths in columns of 28 pixels). Plans made before this was noted are found again by "Precompile picture sizes", in seconds each.': 'Écriture : {done} sur {all} tailles d’image de cette qualité ont leur plan. Manquantes : {missing} (largeurs par colonnes de 28 pixels). Les plans faits avant que cela soit noté sont retrouvés par « Précompiler les tailles d’images », en quelques secondes chacun.',
  'Models run on the processor now, so Exact is used: it reads the same there, as fast, with about 1 GB less memory. The graphics card file is kept for when the card is used again.': 'Les modèles tournent maintenant sur le processeur, donc Exacte est utilisée : elle lit de la même façon là-bas, aussi vite, avec environ 1 Go de mémoire en moins. Le fichier de la carte graphique est conservé pour le jour où la carte sera de nouveau utilisée.',
  'the graphics card is making its plan for this picture size (minutes, once); the processor reads meanwhile': 'la carte graphique établit son plan pour cette taille d’image (quelques minutes, une seule fois) ; le processeur lit en attendant',
  'Always on with CoreML for the "Graphics card" size of the handwriting model: CoreML prepares it once for each picture width (seconds, kept for the next start), so pictures are made one of a few widths.': 'Toujours actif avec CoreML pour la taille « Carte graphique » du modèle d’écriture : CoreML le prépare une fois pour chaque largeur d’image (secondes, conservé pour le prochain démarrage), donc les images sont faites dans quelques largeurs seulement.',
  'Needed with this accelerator: it works out a plan for every picture size it sees, which takes minutes. Pictures of handwriting are made one of a few widths (about a fifth more work) so each plan is made once.': 'Nécessaire avec cet accélérateur : il calcule un plan pour chaque taille d’image qu’il voit, ce qui prend des minutes. Les images d’écriture sont faites dans quelques largeurs seulement (environ un cinquième de travail en plus), pour que chaque plan ne soit fait qu’une fois.',
  'Makes pictures of handwriting one of a few widths, so an accelerator that works out a plan for each size (AMD) does it a few times, not for every line. Costs about a fifth more work; switch it off where the accelerator takes any size.': 'Fait que les images d’écriture ont une de quelques largeurs, de sorte qu’un accélérateur qui calcule un plan pour chaque taille (AMD) le fait quelques fois, et non pour chaque ligne. Coûte environ un cinquième de travail en plus ; désactivez-le là où l’accélérateur accepte n’importe quelle taille.',
  'Line and shape correction': 'Correction des lignes et des formes',
  'How close to straight a line, or to a rectangle, ellipse, triangle or diamond a drawing, must be before it is corrected. Applies to notes opened after the change.': 'À quel point une ligne doit être droite, ou un dessin proche d\'un rectangle, d\'une ellipse, d\'un triangle ou d\'un losange, avant d\'être corrigé. S\'applique aux notes ouvertes après le changement.',
